INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (245, 38, '4', 4, 'calculation', 14.00, '求微分方程\n\[y''x\ln x\cdot\sin y+(1-x\cos y)\cos y=0\]\n的通解。', '通解为 \(\dfrac{1}{\cos y}=\dfrac{x+C}{\ln x}\)。', '将方程变形为\n\[y''\frac{\sin y}{x\ln x}+\frac{\cos y}{\ln x}=\cos^2 y.\]\n令 \(z=\cos y\)，则 \(z''=-\sin y\cdot y''\)，代入得 Bernoulli 方程（\(n=2\)）：\n\[z''-\frac{1}{x\ln x}z=-\frac{1}{\ln x}z^2.\]\n再令 \(u=z^{-1}\)，化为线性方程\n\[u''+\frac{1}{x\ln x}u=\frac{1}{\ln x}.\]\n由一阶线性微分方程通解公式，\n\[u=e^{-\int\frac{dx}{x\ln x}}\left(\int\frac{1}{\ln x}e^{\int\frac{dx}{x\ln x}}dx+C\right) =\frac{1}{\ln x}(x+C).\]\n将 \(u=\dfrac{1}{\cos y}\) 代入，得所求通解\n\[\frac{1}{\cos y}=\frac{x+C}{\ln x}.\]', '2025 年第十七届全国大学生数学竞赛初赛（非数学B类） 求微分方程 [y''x x y+(1-x y) y=0 ] 的通解。 通解为 ( 1 y = x+C x )。 将方程变形为 [y'' y x x + y x = 2 y. ] 令 (z= y )，则 (z''=- y y'' )，代入得 Bernoulli 方程（ (n=2 )）： [z''- 1 x x z=- 1 x z 2. ] 再令 (u=z -1 )，化为线性方程 [u''+ 1 x x u= 1 x . ] 由一阶线性微分方程通解公式， [u=e - dx x x ( 1 x e dx x x dx+C ) = 1 x (x+C). ] 将 (u= 1 y ) 代入，得所求通解 [ 1 y = x+C x . ]', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
