INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (238, 37, '4', 4, 'calculation', 10.00, '求曲面积分\n\[I=\iint_\Sigma\frac{z}{2x^2+y^2+z^2}\,dx\,dy,\]\n其中 \(\Sigma\) 是柱面 \(y^2+z^2=2\) 夹在两平面 \(x=-1\) 与 \(x=1\) 之间的部分，方向取外侧。', '\(I=\dfrac{\pi^2}{2}\)。', '在积分曲面 \(\Sigma\) 上，由曲面方程 \(y^2+z^2=2\) 可将被积函数改写为\n\[\frac{z}{2x^2+y^2+z^2}=\frac{z}{2x^2+2}.\]\n\(\Sigma\) 关于 \(xOz\) 面对称，分为上半部分 \(\Sigma_1:z=\sqrt{2-y^2}\ (z\ge0\)，上侧\()\) 与下半部分 \(\Sigma_2:z=-\sqrt{2-y^2}\ (z\le0\)，下侧\()\)。被积函数关于 \(z\) 为奇函数，由对坐标曲面积分的对称性，\n\[I=2\iint_{\Sigma_1}\frac{z}{2x^2+2}\,dx\,dy =2\iint_D\frac{\sqrt{2-y^2}}{2(x^2+1)}\,dx\,dy,\]\n其中 \(D=\{(x,y)\mid -1\le x\le1,\ -\sqrt2\le y\le\sqrt2\}\) 是 \(\Sigma_1\) 在 \(xOy\) 面上的投影区域。于是\n\[I=\int_{-1}^{1}\frac{dx}{x^2+1}\cdot\int_{-\sqrt2}^{\sqrt2}\sqrt{2-y^2}\,dy =\frac{\pi}{2}\cdot\pi=\frac{\pi^2}{2},\]\n其中 \(\displaystyle\int_{-\sqrt2}^{\sqrt2}\sqrt{2-y^2}\,dy=\pi\) 是半径为 \(\sqrt2\) 的半圆面积。', '2026 年第十七届全国大学生数学竞赛决赛（非数学A类） 求曲面积分 [I= z 2x 2+y 2+z 2 ,dx ,dy, ] 其中 ( ) 是柱面 (y 2+z 2=2 ) 夹在两平面 (x=-1 ) 与 (x=1 ) 之间的部分，方向取外侧。 (I= 2 2 )。 在积分曲面 ( ) 上，由曲面方程 (y 2+z 2=2 ) 可将被积函数改写为 [ z 2x 2+y 2+z 2 = z 2x 2+2 . ] ( ) 关于 (xOz ) 面对称，分为上半部分 ( 1:z= 2-y 2 (z 0 )，上侧 () ) 与下半部分 ( 2:z=- 2-y 2 (z 0 )，下侧 () )。被积函数关于 (z ) 为奇函数，由对坐标曲面积分的对称性， [I=2 1 z 2x 2+2 ,dx ,dy =2 D 2-y 2 2(x 2+1) ,dx ,dy, ] 其中 (D= (x,y) -1 x 1, - 2 y 2 ) 是 ( 1 ) 在 (xOy ) 面上的投影区域。于是 [I= -1 1 dx x 2+1 - 2 2 2-y 2 ,dy = 2 = 2 2 , ] 其中 ( - 2 2 2-y 2 ,dy= ) 是半径为 ( 2 ) 的半圆面积。', 3, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
