INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (217, 34, '2', 2, 'calculation', 14.00, '用 Lagrange 乘数法求函数\n\[f(x,y,z)=x+2y+3z\]\n在平面 \(x-y+z=1\) 与圆柱面 \(x^2+y^2=1\) 的交线上的最大值。', '最大值 \(3+\sqrt{29}\)。', '构造 Lagrange 函数\n\[L(x,y,z;\lambda,\mu)=x+2y+3z-\lambda(x-y+z-1)-\mu(x^2+y^2-1),\]\n由\n\[L_x=1-\lambda-2\mu x=0,\qquad L_y=2+\lambda-2\mu y=0,\qquad L_z=3-\lambda=0,\]\n得 \(\lambda=3\)，\(x=-\dfrac1\mu\)，\(y=\dfrac5{2\mu}\)。代入 \(x^2+y^2=1\)，得\n\[\frac1{\mu^2}+\frac{25}{4\mu^2}=1,\qquad \mu=\pm\frac{\sqrt{29}}2.\]\n于是\n\[(x,y,z)=\left(\mp\frac2{\sqrt{29}},\pm\frac5{\sqrt{29}},1\pm\frac7{\sqrt{29}}\right),\]\n对应函数值\n\[f(x,y,z)=3\pm\sqrt{29}.\]\n故在给定交线上 \(f\) 的最大值为 \(3+\sqrt{29}\)。', '2024 年第十六届全国大学生数学竞赛初赛（非数学B类） 用 Lagrange 乘数法求函数 [f(x,y,z)=x+2y+3z ] 在平面 (x-y+z=1 ) 与圆柱面 (x 2+y 2=1 ) 的交线上的最大值。 最大值 (3+ 29 )。 构造 Lagrange 函数 [L(x,y,z; , )=x+2y+3z- (x-y+z-1)- (x 2+y 2-1), ] 由 [L x=1- -2 x=0, L y=2+ -2 y=0, L z=3- =0, ] 得 ( =3 )， (x=- 1 )， (y= 5 2 )。代入 (x 2+y 2=1 )，得 [ 1 2 + 25 4 2 =1, = 29 2. ] 于是 [(x,y,z)= ( 2 29 , 5 29 ,1 7 29 ), ] 对应函数值 [f(x,y,z)=3 29 . ] 故在给定交线上 (f ) 的最大值为 (3+ 29 )。', 3, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
