INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (219, 34, '4', 4, 'calculation', 14.00, '求微分方程\n\[(x^3-y^2)\,dx+(x^2y+xy)\,dy=0\]\n的通解。', '通解为 \((1+x)\sqrt{x^2+y^2}=Cx\)。', '原方程可化为\n\[x\,dx+y\,dy+\frac{x\,dy-y\,dx}{x^2}\cdot y=0,\]\n即\n\[\frac12d(x^2+y^2)+y\,d\left(\frac yx\right)=0.\]\n两边同除以 \(\sqrt{x^2+y^2}\)，得\n\[d\left(\sqrt{x^2+y^2}\right)+d\left(\sqrt{1+\left(\frac yx\right)^2}\right)=0,\]\n积分得\n\[\sqrt{x^2+y^2}+\sqrt{1+\left(\frac yx\right)^2}=C,\]\n即\n\[\sqrt{x^2+y^2}+\frac{\sqrt{x^2+y^2}}{x}=C,\]\n整理得通解\n\[(1+x)\sqrt{x^2+y^2}=Cx.\]', '2024 年第十六届全国大学生数学竞赛初赛（非数学B类） 求微分方程 [(x 3-y 2) ,dx+(x 2y+xy) ,dy=0 ] 的通解。 通解为 ((1+x) x 2+y 2 =Cx )。 原方程可化为 [x ,dx+y ,dy+ x ,dy-y ,dx x 2 y=0, ] 即 [ 12d(x 2+y 2)+y ,d ( yx )=0. ] 两边同除以 ( x 2+y 2 )，得 [d ( x 2+y 2 )+d ( 1+ ( yx ) 2 )=0, ] 积分得 [ x 2+y 2 + 1+ ( yx ) 2 =C, ] 即 [ x 2+y 2 + x 2+y 2 x =C, ] 整理得通解 [(1+x) x 2+y 2 =Cx. ]', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
