INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (224, 35, '3', 3, 'calculation', 12.00, '设\n\[I=\int_0^{\frac{\pi}{2}}\frac{\sin^2x\cos^2x}{1+\tan^3x}\,dx,\qquad J=\int_0^{\frac{\pi}{2}}\frac{\sin^2x\cos^2x}{1+\cot^3x}\,dx.\]\n证明：\(I=J\)，并求该积分的值。', '\(I=J=\dfrac{\pi}{32}\)。', '作变换 \(x=\dfrac{\pi}{2}-t\)，得\n\[I=\int_0^{\frac{\pi}{2}}\frac{\sin^2t\cos^2t}{1+\cot^3t}\,dt=J.\]\n又\n\[J=\int_0^{\frac{\pi}{2}}\frac{\tan^3x\sin^2x\cos^2x}{1+\tan^3x}\,dx,\]\n故\n\[2I=I+J=\int_0^{\frac{\pi}{2}}\sin^2x\cos^2x\,dx =\frac14\int_0^{\frac{\pi}{2}}\sin^22x\,dx =\frac18\int_0^{\frac{\pi}{2}}(1-\cos4x)\,dx=\frac{\pi}{16},\]\n所以\n\[I=J=\frac{\pi}{32}.\]', '2025 年第十六届全国大学生数学竞赛决赛（非数学B类） 设 [I= 0 2 2x 2x 1+ 3x ,dx, J= 0 2 2x 2x 1+ 3x ,dx. ] 证明： (I=J )，并求该积分的值。 (I=J= 32 )。 作变换 (x= 2 -t )，得 [I= 0 2 2t 2t 1+ 3t ,dt=J. ] 又 [J= 0 2 3x 2x 2x 1+ 3x ,dx, ] 故 [2I=I+J= 0 2 2x 2x ,dx = 14 0 2 22x ,dx = 18 0 2 (1- 4x) ,dx= 16 , ] 所以 [I=J= 32 . ]', 3, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
