INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (225, 35, '4', 4, 'calculation', 12.00, '求微分方程\n\[\frac{yy''''-(y'')^2}{y^2}=\ln y\]\n的通解。', '通解为 \(\ln y=C_1e^x+C_2e^{-x}\)。', '因为\n\[\left(\frac{y''}{y}\right)''=\frac{yy''''-(y'')^2}{y^2},\]\n所以原方程化为\n\[(\ln y)''''=\ln y.\]\n令 \(z=\ln y\)，则 \(z''''=z\)，解得\n\[z=C_1e^x+C_2e^{-x},\]\n故通解为\n\[\ln y=C_1e^x+C_2e^{-x}.\]', '2025 年第十六届全国大学生数学竞赛决赛（非数学B类） 求微分方程 [ yy''''-(y'') 2 y 2 = y ] 的通解。 通解为 ( y=C 1e x+C 2e -x )。 因为 [ ( y'' y )''= yy''''-(y'') 2 y 2 , ] 所以原方程化为 [( y)''''= y. ] 令 (z= y )，则 (z''''=z )，解得 [z=C 1e x+C 2e -x , ] 故通解为 [ y=C 1e x+C 2e -x . ]', 4, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
