INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (198, 31, '2', 2, 'calculation', 14.00, '设曲线 \(y=3ax^2+2bx+\ln c\) 过点 \((0,0)\)，且当 \(0\le x\le1\) 时 \(y\ge0\)。设该曲线与直线 \(x=1\)、\(x\) 轴所围平面区域 \(D\) 的面积为 \(1\)。求常数 \(a,b,c\) 的值，使得 \(D\) 绕 \(x\) 轴旋转所得旋转体的体积最小。', '\(a=-\dfrac54,\quad b=\dfrac94,\quad c=1\)。', '由曲线过 \((0,0)\) 得 \(\ln c=0\)，即 \(c=1\)。区域 \(D\) 的面积为\n\[A=\int_0^1(3ax^2+2bx)dx=a+b=1.\]\n旋转体体积\n\[V=\pi\int_0^1(3ax^2+2bx)^2dx=\pi\left(\frac95a^2+3ab+\frac43b^2\right).\]\n由 \(b=1-a\) 得\n\[V=\pi\left(\frac2{15}a^2+\frac13a+\frac43\right),\qquad V''(a)=\pi\left(\frac4{15}a+\frac13\right).\]\n令 \(V''(a)=0\)，得 \(a=-\dfrac54\)，此时 \(b=\dfrac94\)，且 \(V\) 取得极小值。故 \(a=-\dfrac54,\ b=\dfrac94,\ c=1\)。', '2023 年第十五届全国大学生数学竞赛初赛（非数学B类） 设曲线 (y=3ax 2+2bx+ c ) 过点 ((0,0) )，且当 (0 x 1 ) 时 (y 0 )。设该曲线与直线 (x=1 )、 (x ) 轴所围平面区域 (D ) 的面积为 (1 )。求常数 (a,b,c ) 的值，使得 (D ) 绕 (x ) 轴旋转所得旋转体的体积最小。 (a=- 54, b= 94, c=1 )。 由曲线过 ((0,0) ) 得 ( c=0 )，即 (c=1 )。区域 (D ) 的面积为 [A= 0 1(3ax 2+2bx)dx=a+b=1. ] 旋转体体积 [V= 0 1(3ax 2+2bx) 2dx= ( 95a 2+3ab+ 43b 2 ). ] 由 (b=1-a ) 得 [V= ( 2 15 a 2+ 13a+ 43 ), V''(a)= ( 4 15 a+ 13 ). ] 令 (V''(a)=0 )，得 (a=- 54 )，此时 (b= 94 )，且 (V ) 取得极小值。故 (a=- 54, b= 94, c=1 )。', 3, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
