INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (169, 26, '6', 6, 'proof', 10.00, '证明：若 \(a>0,b>0,a+b=1\)，则\n\[a^b+b^a\le\sqrt a+\sqrt b\le a^a+b^b.\]', '所给双边不等式成立。', '不妨设 \(0<a\le1/2\le b<1\)，考虑 \(F(x)=a^x+b^{1-x}\)。证明其在 \((0,b]\) 单调减少，则 \(F(b)\le F(1/2)\le F(a)\)，即得结论。', '2023 年第十三届全国大学生数学竞赛决赛（非数学类） 证明：若 (a>0,b>0,a+b=1 )，则 [a b+b a a+ b a a+b b. ] 所给双边不等式成立。 不妨设 (0<a 1/2 b<1 )，考虑 (F(x)=a x+b 1-x )。证明其在 ((0,b] ) 单调减少，则 (F(b) F(1/2) F(a) )，即得结论。', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
