INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (148, 23, '5', 5, 'calculation', 12.00, '计算 \(I=\oint_\Gamma(3y-x)\,dx-5z\,dz\)，其中 \(\Gamma\) 为 \(x^2+y^2+z^2=8\) 与 \(x^2+y^2=2z\) 的交线，从 \(z\) 轴正向看取逆时针方向。', '\(I=0\)。', '联立得 \(z=2,x^2+y^2=4\)。取 \(x=2\cos t,y=2\sin t,z=2\) 代入一周积分即得。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 计算 (I= (3y-x) ,dx-5z ,dz )，其中 ( ) 为 (x 2+y 2+z 2=8 ) 与 (x 2+y 2=2z ) 的交线，从 (z ) 轴正向看取逆时针方向。 (I=0 )。 联立得 (z=2,x 2+y 2=4 )。取 (x=2 t,y=2 t,z=2 ) 代入一周积分即得。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
