INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (149, 23, '6', 6, 'proof', 12.00, '定义 \(\displaystyle f(n)=\sum_{m=1}^n\int_0^m\cos\frac{2\pi n[x+1]}m\,dx\)。证明 \(f(n)\) 等于 \(n\) 的所有正因子之和，并计算 \(f(2021)\)。', '\(f(n)=\sigma(n)\)，且 \(f(2021)=2112\)。', '把积分按单位区间分割成单位根之和：当 \(m\mid n\) 时为 \(m\)，否则为 0。又 \(2021=43\times47\)，故 \((1+43)(1+47)=2112\)。', '2020 年第十二届全国大学生数学竞赛初赛（非数学类） 定义 ( f(n)= m=1 n 0 m 2 n[x+1] m ,dx )。证明 (f(n) ) 等于 (n ) 的所有正因子之和，并计算 (f(2021) )。 (f(n)= (n) )，且 (f(2021)=2112 )。 把积分按单位区间分割成单位根之和：当 (m n ) 时为 (m )，否则为 0。又 (2021=43 47 )，故 ((1+43)(1+47)=2112 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
