INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (151, 24, '1', 1, 'calculation', 30.00, '填空题，共 5 小题，每小题 6 分。\n\n1. 求 \(\displaystyle\lim_{n\to\infty}\sum_{k=1}^n\frac{k}{n^2}\sin^2\left(1+\frac{k}{n}\right)\)。\n2. \(u=xyz+e^{xyz}\)，求其在 \(P_0(1,1,-1)\) 沿 \(P_0P_1\)（\(P_1=(2,-1,0)\)）方向的方向导数。\n3. \(\Gamma:x^2+y^2+z^2=a^2,x+y+z=0\)，求 \(\displaystyle\oint_\Gamma(1+x)^2ds\)。\n4. 三阶矩阵 \(A\) 满足 \(|A^*|=16,|A|>0\)，且 \(ABA^{-1}=BA^{-1}+3I\)，求 \(B\)。\n5. \(u=x_1+x_2/x_1+x_3/x_2+2/x_3\ (x_i>0)\)，求全部极值点。', '1. \(\displaystyle\frac{2-2\sin4-\cos4+\cos2}{8}\)。\n2. \(\displaystyle\frac{2(1+e^{-1})}{\sqrt6}\)。 3. \(\displaystyle2\pi a(1+a^2/3)\)。\n4. \(\displaystyle B=3(I-A^{-1})^{-1}=3(I-A^*/4)^{-1}\)。\n5. 唯一极值点 \(\displaystyle(2^{1/4},2^{1/2},2^{3/4})\)，为极小值点。', '1. 化为 Riemann 积分。 2. 梯度点乘单位方向向量。 3. 利用圆周关于 \(x,y,z\) 的对称性。\n4. 由 \(|A^*|=|A|^2\) 得 \(|A|=4\)，再整理矩阵方程。 5. 用 AM-GM 或驻点方程。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( n k=1 n k n 2 2 (1+ k n ) )。 2. (u=xyz+e xyz )，求其在 (P 0(1,1,-1) ) 沿 (P 0P 1 )（ (P 1=(2,-1,0) )）方向的方向导数。 3. ( :x 2+y 2+z 2=a 2,x+y+z=0 )，求 ( (1+x) 2ds )。 4. 三阶矩阵 (A ) 满足 (|A *|=16,|A|>0 )，且 (ABA -1 =BA -1 +3I )，求 (B )。 5. (u=x 1+x 2/x 1+x 3/x 2+2/x 3 (x i>0) )，求全部极值点。 1. ( 2-2 4- 4+ 2 8 )。 2. ( 2(1+e -1 ) 6 )。 3. ( 2 a(1+a 2/3) )。 4. ( B=3(I-A -1 ) -1 =3(I-A */4) -1 )。 5. 唯一极值点 ( (2 1/4 ,2 1/2 ,2 3/4 ) )，为极小值点。 1. 化为 Riemann 积分。 2. 梯度点乘单位方向向量。 3. 利用圆周关于 (x,y,z ) 的对称性。 4. 由 (|A *|=|A| 2 ) 得 (|A|=4 )，再整理矩阵方程。 5. 用 AM-GM 或驻点方程。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
