INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (152, 24, '2', 2, 'calculation', 12.00, '设 \(n\) 为正整数，求\n\[\lim_{x\to0}\frac{\displaystyle\prod_{k=1}^n\left(\frac{1+kx}{1-kx}\right)^{1/(2k)}-1}{3\pi\arcsin x-(1+x^2)\arctan^3x}.\]', '\(\displaystyle\frac{n}{3\pi}\)。', '记乘积为 \(f(x)\)，对数求导得 \(f(0)=1,f''(0)=n\)。分母等价于 \(3\pi x\)，故极限为 \(n/(3\pi)\)。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (n ) 为正整数，求 [ x 0 k=1 n ( 1+kx 1-kx ) 1/(2k) -1 3 x-(1+x 2) 3x . ] ( n 3 )。 记乘积为 (f(x) )，对数求导得 (f(0)=1,f''(0)=n )。分母等价于 (3 x )，故极限为 (n/(3 ) )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
