INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (155, 24, '5', 5, 'comprehensive', 12.00, '设 \(A\) 是 \(n\) 阶实对称矩阵。证明存在唯一实对称矩阵 \(B\)，使 \(B^{2021}=A\)、\(AB=BA\)，且存在多项式 \(p\) 使 \(B=p(A)\)。', '所述实对称奇次方根存在、可表示为 \(p(A)\)，且唯一。', '正交对角化 \(A\)，对每个实特征值取唯一实 2021 次根构造 \(B\)；用 Lagrange 插值构造 \(p\)。标量奇次根唯一给出矩阵解唯一。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (A ) 是 (n ) 阶实对称矩阵。证明存在唯一实对称矩阵 (B )，使 (B 2021 =A )、 (AB=BA )，且存在多项式 (p ) 使 (B=p(A) )。 所述实对称奇次方根存在、可表示为 (p(A) )，且唯一。 正交对角化 (A )，对每个实特征值取唯一实 2021 次根构造 (B )；用 Lagrange 插值构造 (p )。标量奇次根唯一给出矩阵解唯一。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
