INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (156, 24, '6', 6, 'proof', 12.00, '设 \(A_n(x,y)=\sum_{k=0}^nx^{n-k}y^k\)，\(0<x,y<1\)。证明\n\[\frac2{2-x-y}\le\sum_{n=0}^\infty\frac{A_n(x,y)}{n+1}\le\frac12\left(\frac1{1-x}+\frac1{1-y}\right).\]', '所给双边不等式成立。', '逐项证明 \(((x+y)/2)^n\le A_n/(n+1)\le(x^n+y^n)/2\)，再对 \(n\) 求和。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (A n(x,y)= k=0 nx n-k y k )， (0<x,y<1 )。证明 [ 2 2-x-y n=0 A n(x,y) n+1 12 ( 1 1-x + 1 1-y ). ] 所给双边不等式成立。 逐项证明 (((x+y)/2) n A n/(n+1) (x n+y n)/2 )，再对 (n ) 求和。', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
