INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (157, 24, '7', 7, 'proof', 10.00, '设 \(f,g:[0,1]\to[0,1]\) 连续，且 \(f\) 单调增加。证明\n\[\int_0^1f(g(x))dx\le\int_0^1f(x)dx+\int_0^1g(x)dx.\]', '所给积分不等式成立。', '令 \(F(x)=f(x)-x\)，估计 \(\max F-\int_0^1F\le1/2\)，代入 \(F(g(x))\) 并整理即得。', '2021 年第十二届全国大学生数学竞赛决赛（非数学类） 设 (f,g:[0,1] [0,1] ) 连续，且 (f ) 单调增加。证明 [ 0 1f(g(x))dx 0 1f(x)dx+ 0 1g(x)dx. ] 所给积分不等式成立。 令 (F(x)=f(x)-x )，估计 ( F- 0 1F 1/2 )，代入 (F(g(x)) ) 并整理即得。', 6, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
