INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (131, 21, '1', 1, 'calculation', 30.00, '填空题，共 5 小题，每小题 6 分。\n\n1. 求 \(\displaystyle\lim_{x\to0}\frac{\ln(e^{\sin x}+\sqrt[3]{1-\cos x})-\sin x}{\arctan(4\sqrt[3]{1-\cos x})}\)。\n2. 曲线 \(y^2(x-y)=x^2\)，求 \(\displaystyle\int\frac{dx}{y^2}\)。\n3. 求 \(\displaystyle\int_0^{\pi/2}\frac{e^x(1+\sin x)}{(1+\cos x)^2}\,dx\)。\n4. 求全微分 \(\displaystyle du=\frac{y\,dx-x\,dy}{3x^2-2xy+3y^2}\) 的原函数。\n5. 曲面 \(xyz=\mu\) 与椭球 \(x^2/a^2+y^2/b^2+z^2/c^2=1\) 相切，求 \(\mu\)。', '1. \(1/4\)。 2. \(\displaystyle3y/x-2\ln|y/x|+C\)。 3. \(e^{\pi/2}\)。\n4. \(\displaystyle u=\frac1{2\sqrt2}\arctan\left[\frac3{2\sqrt2}\left(\frac{x}{y}-\frac13\right)\right]+C\)。\n5. \(\displaystyle\mu=\frac{abc}{3\sqrt3}\)。', '1. 展开分子分母的最低阶项。 2. 利用隐式关系令 \(u=y/x\) 化为可积形式。\n3. 识别为 \(e^x/(1+\cos x)\) 的导数。 4. 令 \(t=x/y\) 后积分。\n5. 用 Lagrange 乘子或 AM-GM 求椭球上 \(xyz\) 的极值。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求 ( x 0 (e x + [3] 1- x )- x (4 [3] 1- x ) )。 2. 曲线 (y 2(x-y)=x 2 )，求 ( dx y 2 )。 3. 求 ( 0 /2 e x(1+ x) (1+ x) 2 ,dx )。 4. 求全微分 ( du= y ,dx-x ,dy 3x 2-2xy+3y 2 ) 的原函数。 5. 曲面 (xyz= ) 与椭球 (x 2/a 2+y 2/b 2+z 2/c 2=1 ) 相切，求 ( )。 1. (1/4 )。 2. ( 3y/x-2 |y/x|+C )。 3. (e /2 )。 4. ( u= 1 2 2 [ 3 2 2 ( x y - 13 ) ]+C )。 5. ( = abc 3 3 )。 1. 展开分子分母的最低阶项。 2. 利用隐式关系令 (u=y/x ) 化为可积形式。 3. 识别为 (e x/(1+ x) ) 的导数。 4. 令 (t=x/y ) 后积分。 5. 用 Lagrange 乘子或 AM-GM 求椭球上 (xyz ) 的极值。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
