INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (133, 21, '3', 3, 'proof', 14.00, '设 \(f\) 在 \([0,\infty)\) 可导，\(f(0)=0\)，且存在常数 \(A>0\) 使 \(|f''(x)|\le A|f(x)|\)。证明 \(f(x)\equiv0\)。', '\(f\equiv0\)。', '令 \(F(x)=\int_0^x|f(t)|dt\)，则 \(|f(x)|\le A F(x)\)，从而 \(F''(x)\le AF(x)\)、\(F(0)=0\)。乘以 \(e^{-Ax}\) 后得 \(F\equiv0\)。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0, ) ) 可导， (f(0)=0 )，且存在常数 (A>0 ) 使 (|f''(x)| A|f(x)| )。证明 (f(x) 0 )。 (f 0 )。 令 (F(x)= 0 x|f(t)|dt )，则 (|f(x)| A F(x) )，从而 (F''(x) AF(x) )、 (F(0)=0 )。乘以 (e -Ax ) 后得 (F 0 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
