INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (135, 21, '5', 5, 'proof', 14.00, '设多项式 \(f(x)\) 的根全为正实数，并在原点附近展开\n\[-\frac{f''(x)}{f(x)}=\sum_{n=0}^\infty c_nx^n.\]\n证明 \(c_n>0\)，且 \(\displaystyle\lim_{n\to\infty}c_n^{-1/n}\) 等于 \(f\) 的最小正根。', '各 \(c_n>0\)，所给极限等于最小正根。', '若各根为 \(r_j>0\)，则 \(-f''/f=\sum_j1/(r_j-x)=\sum_{n\ge0}(\sum_jr_j^{-n-1})x^n\)。因此系数为正；最大项由最小根控制，取 \(n\) 次根即得结论。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 设多项式 (f(x) ) 的根全为正实数，并在原点附近展开 [- f''(x) f(x) = n=0 c nx n. ] 证明 (c n>0 )，且 ( n c n -1/n ) 等于 (f ) 的最小正根。 各 (c n>0 )，所给极限等于最小正根。 若各根为 (r j>0 )，则 (-f''/f= j1/(r j-x)= n 0 ( jr j -n-1 )x n )。因此系数为正；最大项由最小根控制，取 (n ) 次根即得结论。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
