INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (136, 21, '6', 6, 'proof', 14.00, '函数 \(f\) 满足\n\[3[3+f^2(x)]f''(x)=2[1+f^2(x)]^2e^{-x^2},\qquad f(0)\le1.\]\n证明 \(f\) 在实轴上有界。', '\(f\) 在 \(\mathbb R\) 上有界。', '分离变量并注意 \(\frac{3(3+u^2)}{2(1+u^2)^2}\) 在无穷远可积，而右端 \(e^{-x^2}\) 的总积分有限。结合初值上界比较可知解不能在有限或无限区间逃向无穷。', '2019 年第十一届全国大学生数学竞赛初赛（非数学类） 函数 (f ) 满足 [3[3+f 2(x)]f''(x)=2[1+f 2(x)] 2e -x 2 , f(0) 1. ] 证明 (f ) 在实轴上有界。 (f ) 在 ( R ) 上有界。 分离变量并注意 ( 3(3+u 2) 2(1+u 2) 2 ) 在无穷远可积，而右端 (e -x 2 ) 的总积分有限。结合初值上界比较可知解不能在有限或无限区间逃向无穷。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
