INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (140, 22, '4', 4, 'proof', 10.00, '设 \(f\in C^1[0,1]\)，且 \(\int_0^1f(x)dx=5/2\)、\(\int_0^1xf(x)dx=3/2\)。证明存在 \(\xi\in(0,1)\)，使 \(f''(\xi)=3\)。', '所述 \(\xi\) 存在。', '计算 \(\int_0^1x(1-x)[3-f''(x)]dx\)，分部积分并代入两矩条件得零。由积分中值定理且权函数在内部为正，得 \(f''(\xi)=3\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设 (f C 1[0,1] )，且 ( 0 1f(x)dx=5/2 )、 ( 0 1xf(x)dx=3/2 )。证明存在 ( (0,1) )，使 (f''( )=3 )。 所述 ( ) 存在。 计算 ( 0 1x(1-x)[3-f''(x)]dx )，分部积分并代入两矩条件得零。由积分中值定理且权函数在内部为正，得 (f''( )=3 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
