INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (142, 22, '6', 6, 'proof', 12.00, '设 \(\Omega\) 的边界为光滑闭曲面 \(\Sigma\)，\(f\in C^2(\Omega)\) 且 \(f|_\Sigma=0\)。证明对任意 \(C>0\)，\n\[C\iiint_\Omega f^2dV+\frac1C\iiint_\Omega(\Delta f)^2dV\ge2\iiint_\Omega|\nabla f|^2dV.\]', '所给积分不等式成立。', '由 Green 第一恒等式及边界值为零，\(\int|\nabla f|^2=-\int f\Delta f\)。再对 \(\sqrt C f\) 与 \(\Delta f/\sqrt C\) 用 Cauchy 不等式。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设 ( ) 的边界为光滑闭曲面 ( )， (f C 2( ) ) 且 (f| =0 )。证明对任意 (C>0 )， [C f 2dV+ 1C ( f) 2dV 2 | f| 2dV. ] 所给积分不等式成立。 由 Green 第一恒等式及边界值为零， ( | f| 2=- f f )。再对 ( C f ) 与 ( f/ C ) 用 Cauchy 不等式。', 5, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
