INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (143, 22, '7', 7, 'comprehensive', 12.00, '设正数列满足\n\[\frac{u_{n+1}}{u_n}=1-\frac\alpha n+O(n^{-\beta}),\qquad\beta>1.\]\n令 \(v_n=n^\alpha u_n\)。证明 \(v_n\) 有正的有限极限，并判断 \(\sum u_n\) 的敛散性。', '\(v_n\to C\in(0,\infty)\)；\(\sum u_n\) 当且仅当 \(\alpha>1\) 时收敛。', '展开 \(\ln(v_{n+1}/v_n)\)，一次项抵消，余项为 \(O(n^{-2})+O(n^{-\beta})\)，其级数绝对收敛，故乘积趋于正有限值。于是 \(u_n\sim Cn^{-\alpha}\)，与 \(p\)-级数比较即得。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 设正数列满足 [ u n+1 u n =1- n+O(n - ), >1. ] 令 (v n=n u n )。证明 (v n ) 有正的有限极限，并判断 ( u n ) 的敛散性。 (v n C (0, ) )； ( u n ) 当且仅当 ( >1 ) 时收敛。 展开 ( (v n+1 /v n) )，一次项抵消，余项为 (O(n -2 )+O(n - ) )，其级数绝对收敛，故乘积趋于正有限值。于是 (u n Cn - )，与 (p )-级数比较即得。', 6, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
