INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (119, 19, '3', 3, 'proof', 14.00, '设 \(f\) 在 \([0,1]\) 连续，且 \(1\le f(x)\le3\)。证明\n\[1\le\int_0^1f(x)\,dx\int_0^1\frac{dx}{f(x)}\le\frac43.\]', '所给双边不等式成立。', '下界由 Cauchy 不等式。上界利用 \((f-1)(3-f)\ge0\)，即 \(f+3/f\le4\)，积分后结合算术—几何平均不等式即得。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 连续，且 (1 f(x) 3 )。证明 [1 0 1f(x) ,dx 0 1 dx f(x) 43. ] 所给双边不等式成立。 下界由 Cauchy 不等式。上界利用 ((f-1)(3-f) 0 )，即 (f+3/f 4 )，积分后结合算术—几何平均不等式即得。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
