INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (121, 19, '5', 5, 'proof', 14.00, '设 \(f(x,y)\) 在区域 \(D\) 内可微，且 \(\sqrt{f_x^2+f_y^2}\le M\)。若线段 \(AB\subset D\)，证明\n\[|f(A)-f(B)|\le M|AB|.\]', '所给 Lipschitz 估计成立。', '参数化线段 \(X(t)=A+t(B-A)\)。对 \(f(X(t))\) 用一元中值定理，再由 Cauchy 不等式估计方向导数不超过 \(M|AB|\)。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 设 (f(x,y) ) 在区域 (D ) 内可微，且 ( f x 2+f y 2 M )。若线段 (AB D )，证明 [|f(A)-f(B)| M|AB|. ] 所给 Lipschitz 估计成立。 参数化线段 (X(t)=A+t(B-A) )。对 (f(X(t)) ) 用一元中值定理，再由 Cauchy 不等式估计方向导数不超过 (M|AB| )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
