INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (123, 19, '7', 7, 'proof', 14.00, '已知正数列 \(\{a_k\},\{b_k\}\) 满足 \(b_{k+1}-b_k\ge\delta>0\)。证明：若 \(\sum_{k=1}^\infty a_k\) 收敛，则\n\[\sum_{k=1}^\infty\frac{\sqrt[k]{(a_1a_2\cdots a_k)(b_1b_2\cdots b_k)}}{b_{k+1}b_k}\]\n收敛。', '所给正项级数收敛。', '令 \(S_k=\sum_{i=1}^ka_ib_i\)。对 \(\sum a_k\) 作 Abel 变换，并用 \(b_{k+1}-b_k\ge\delta\)，可得 \(\sum S_k/(b_kb_{k+1})\) 收敛。又由算术—几何平均不等式，\(\sqrt[k]{\prod_{i=1}^ka_ib_i}\le S_k/k\le S_k\)，比较即得。', '2018 年第十届全国大学生数学竞赛初赛（非数学类） 已知正数列 ( a k , b k ) 满足 (b k+1 -b k >0 )。证明：若 ( k=1 a k ) 收敛，则 [ k=1 [k] (a 1a 2 a k)(b 1b 2 b k) b k+1 b k ] 收敛。 所给正项级数收敛。 令 (S k= i=1 ka ib i )。对 ( a k ) 作 Abel 变换，并用 (b k+1 -b k )，可得 ( S k/(b kb k+1 ) ) 收敛。又由算术—几何平均不等式， ( [k] i=1 ka ib i S k/k S k )，比较即得。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
