INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (110, 18, '1', 1, 'calculation', 30.00, '填空题，共 5 小题，每小题 6 分。\n\n1. 求 \(\displaystyle\lim_{x\to0}\frac{\tan x-\sin x}{x\ln(1+\sin^2x)}\)。\n2. 求经过原点与点 \((6,-3,2)\)，且垂直于平面 \(4x-y+2z=8\) 的平面。\n3. 若 \(df=ye^y\,dx+x(1+y)e^y\,dy\)、\(f(0,0)=0\)，求 \(f(x,y)\)。\n4. 可微函数满足 \(u''(t)=u(t)+\int_0^1u(t)dt\)、\(u(0)=1\)，求 \(u(t)\)。\n5. 正实数 \(a,b,c,d\) 两两不同，实数 \(x,y,z,w\) 满足 \(a^x=bc^zd^w,b^y=c^zd^wa^x,c^z=d^wa^xb^y,d^w=a^xb^yc^z\)。求矩阵对角元 \(-x,-y,-z,-w\)、其余元为 1 的行列式。', '1. \(1/2\)。 2. \(2x+2y-3z=0\)。 3. \(f=xye^y\)。\n4. \(\displaystyle u(t)=\frac{2e^t-e+1}{3-e}\)。 5. \(0\)。', '1. Taylor 展开到最低非零阶。2. 所求法向量同时垂直给定平面法向量与点向量。\n3. 识别全微分。4. 记常数 \(C=\int_0^1u\)，解 \(u''=u+C\) 后再积分确定 \(C\)。\n5. 对四个幂等式取对数，所得齐次线性方程有非零解，故系数行列式为零。', '2018 年第九届全国大学生数学竞赛决赛（非数学专业） 填空题，共 5 小题，每小题 6 分。 1. 求 ( x 0 x- x x (1+ 2x) )。 2. 求经过原点与点 ((6,-3,2) )，且垂直于平面 (4x-y+2z=8 ) 的平面。 3. 若 (df=ye y ,dx+x(1+y)e y ,dy )、 (f(0,0)=0 )，求 (f(x,y) )。 4. 可微函数满足 (u''(t)=u(t)+ 0 1u(t)dt )、 (u(0)=1 )，求 (u(t) )。 5. 正实数 (a,b,c,d ) 两两不同，实数 (x,y,z,w ) 满足 (a x=bc zd w,b y=c zd wa x,c z=d wa xb y,d w=a xb yc z )。求矩阵对角元 (-x,-y,-z,-w )、其余元为 1 的行列式。 1. (1/2 )。 2. (2x+2y-3z=0 )。 3. (f=xye y )。 4. ( u(t)= 2e t-e+1 3-e )。 5. (0 )。 1. Taylor 展开到最低非零阶。2. 所求法向量同时垂直给定平面法向量与点向量。 3. 识别全微分。4. 记常数 (C= 0 1u )，解 (u''=u+C ) 后再积分确定 (C )。 5. 对四个幂等式取对数，所得齐次线性方程有非零解，故系数行列式为零。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
