INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (111, 18, '2', 2, 'proof', 11.00, '连续函数 \(f\) 在 \((0,1)\) 内有两组割线斜率 \(\alpha<\beta\)。证明对任意 \(\lambda\in(\alpha,\beta)\)，存在互异 \(x_5,x_6\in(0,1)\)，使割线斜率为 \(\lambda\)。', '任意中间斜率均可由一条割线取得。', '把两组端点分别线性插值，构造连续的割线斜率函数 \(F(t)\)，使 \(F(0)=\alpha,F(1)=\beta\)。由介值定理取 \(F(t_0)=\lambda\)，对应两插值点仍互异且位于 \((0,1)\)。', '2018 年第九届全国大学生数学竞赛决赛（非数学专业） 连续函数 (f ) 在 ((0,1) ) 内有两组割线斜率 ( < )。证明对任意 ( ( , ) )，存在互异 (x 5,x 6 (0,1) )，使割线斜率为 ( )。 任意中间斜率均可由一条割线取得。 把两组端点分别线性插值，构造连续的割线斜率函数 (F(t) )，使 (F(0)= ,F(1)= )。由介值定理取 (F(t 0)= )，对应两插值点仍互异且位于 ((0,1) )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
