INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (112, 18, '3', 3, 'proof', 11.00, '设 \(f\) 在 \([0,1]\) 连续且 \(\int_0^1f(x)\,dx\ne0\)。证明存在三个不同的点 \(x_1,x_2,x_3\in[0,1]\)，使\n\[\frac\pi8\int_0^1f(x)\,dx=\left[\frac1{1+x_1^2}\int_0^{x_1}f(t)\,dt+f(x_1)\arctan x_1\right]x_3\]\n\[=\left[\frac1{1+x_2^2}\int_0^{x_2}f(t)\,dt+f(x_2)\arctan x_2\right](1-x_3).\]', '所述三个不同点存在。', '令 \(F(x)=\frac{4\arctan x\int_0^xf(t)dt}{\pi\int_0^1f(t)dt}\)，则 \(F(0)=0,F(1)=1\)。先由介值定理取 \(F(x_3)=1/2\)，再分别在 \([0,x_3]\)、\([x_3,1]\) 用 Lagrange 中值定理，即得分居两侧的 \(x_1,x_2\) 和题设两式。', '2018 年第九届全国大学生数学竞赛决赛（非数学专业） 设 (f ) 在 ([0,1] ) 连续且 ( 0 1f(x) ,dx 0 )。证明存在三个不同的点 (x 1,x 2,x 3 [0,1] )，使 [ 8 0 1f(x) ,dx= [ 1 1+x 1 2 0 x 1 f(t) ,dt+f(x 1) x 1 ]x 3 ] [= [ 1 1+x 2 2 0 x 2 f(t) ,dt+f(x 2) x 2 ](1-x 3). ] 所述三个不同点存在。 令 (F(x)= 4 x 0 xf(t)dt 0 1f(t)dt )，则 (F(0)=0,F(1)=1 )。先由介值定理取 (F(x 3)=1/2 )，再分别在 ([0,x 3] )、 ([x 3,1] ) 用 Lagrange 中值定理，即得分居两侧的 (x 1,x 2 ) 和题设两式。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
