INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (113, 18, '4', 4, 'calculation', 12.00, '求 \(\displaystyle\lim_{n\to\infty}\left(\sqrt[n+1]{(n+1)!}-\sqrt[n]{n!}\right)\)。', '\(1/e\)。', '写成 \(\sqrt[n]{n!}\bigl(\sqrt[n+1]{(n+1)!}/\sqrt[n]{n!}-1\bigr)\)。Riemann 和给出 \(\sqrt[n]{n!}/n\to e^{-1}\)，对括号用指数等价无穷小可得乘以 \(n\) 后趋于 1，故极限为 \(1/e\)。', '2018 年第九届全国大学生数学竞赛决赛（非数学专业） 求 ( n ( [n+1] (n+1)! - [n] n! ) )。 (1/e )。 写成 ( [n] n! ( [n+1] (n+1)! / [n] n! -1 ) )。Riemann 和给出 ( [n] n! /n e -1 )，对括号用指数等价无穷小可得乘以 (n ) 后趋于 1，故极限为 (1/e )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
