INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (116, 18, '7', 7, 'comprehensive', 12.00, '设 \(0<a_n<1\)，且 \(\displaystyle\frac{\ln(1/a_n)}{\ln n}\to q\)（有限或 \(+\infty\)）。\n\n1. 证明 \(q>1\) 时 \(\sum a_n\) 收敛，\(q<1\) 时发散；\n2. 讨论 \(q=1\) 时的敛散性。', '1. 结论如题。 2. \(q=1\) 时可能收敛，也可能发散。', '当 \(q>1\) 时选 \(1<p<q\)，充分大时 \(a_n<n^{-p}\)；当 \(q<1\) 时选 \(q<p<1\)，充分大时 \(a_n>n^{-p}\)。当 \(q=1\) 时，\(a_n=1/n\) 给出发散例，\(a_n=1/[n(\ln n)^2]\) 给出收敛例。', '2018 年第九届全国大学生数学竞赛决赛（非数学专业） 设 (0<a n<1 )，且 ( (1/a n) n q )（有限或 (+ )）。 1. 证明 (q>1 ) 时 ( a n ) 收敛， (q<1 ) 时发散； 2. 讨论 (q=1 ) 时的敛散性。 1. 结论如题。 2. (q=1 ) 时可能收敛，也可能发散。 当 (q>1 ) 时选 (1<p<q )，充分大时 (a n<n -p )；当 (q<1 ) 时选 (q<p<1 )，充分大时 (a n>n -p )。当 (q=1 ) 时， (a n=1/n ) 给出发散例， (a n=1/[n( n) 2] ) 给出收敛例。', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
