INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (94, 15, '2', 2, 'proof', 14.00, '设 \(f\) 在 \([0,1]\) 上可导，\(f(0)=0\)，且 \(0<f''(x)<1\ (0<x<1)\)。证明对 \(a\in(0,1)\)，\n\[\left(\int_0^af(x)\,\mathrm dx\right)^2>\int_0^af^3(x)\,\mathrm dx.\]', '所给严格不等式成立。', '令 \(F(x)=(\int_0^xf)^2-\int_0^xf^3\)，又令 \(g(x)=2\int_0^xf-f^2(x)\)。由 \(f>0\) 及 \(g''(x)=2f(x)[1-f''(x)]>0\)，得 \(F''(x)=f(x)g(x)>0\)。所以 \(F(a)>F(0)=0\)。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 上可导， (f(0)=0 )，且 (0<f''(x)<1 (0<x<1) )。证明对 (a (0,1) )， [ ( 0 af(x) , dx ) 2> 0 af 3(x) , dx. ] 所给严格不等式成立。 令 (F(x)=( 0 xf) 2- 0 xf 3 )，又令 (g(x)=2 0 xf-f 2(x) )。由 (f>0 ) 及 (g''(x)=2f(x)[1-f''(x)]>0 )，得 (F''(x)=f(x)g(x)>0 )。所以 (F(a)>F(0)=0 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
