INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (95, 15, '3', 3, 'calculation', 14.00, '区域 \(\Omega:x^2+y^2+2z^2\le x+y+2z\)，密度为 \(x^2+y^2+z^2\)。求质量\n\[M=\iiint_\Omega(x^2+y^2+z^2)\,\mathrm dx\,\mathrm dy\,\mathrm dz.\]', '\(M=5\pi/6\)。', '令 \(u=x-1/2,v=y-1/2,w=2(z-1/2)\)，区域化为单位球，Jacobi 行列式为 \(1/2\)。奇函数项积分为零，利用球域轮换对称性和球坐标积分，得到 \(M=5\pi/6\)。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 区域 ( :x 2+y 2+2z 2 x+y+2z )，密度为 (x 2+y 2+z 2 )。求质量 [M= (x 2+y 2+z 2) , dx , dy , dz. ] (M=5 /6 )。 令 (u=x-1/2,v=y-1/2,w=2(z-1/2) )，区域化为单位球，Jacobi 行列式为 (1/2 )。奇函数项积分为零，利用球域轮换对称性和球坐标积分，得到 (M=5 /6 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
