INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (96, 15, '4', 4, 'proof', 14.00, '设 \(f\in C^1[0,1]\)，\(f(0)=0,f(1)=1\)。证明\n\[\lim_{n\to\infty}n\left[\int_0^1f(x)\,\mathrm dx-\frac1n\sum_{k=1}^nf(k/n)\right]=-\frac12.\]', '极限为 \(-1/2\)。', '把积分按 \(n\) 等分并与右端点 Riemann 和逐段相减，用中值定理写成 \(-\frac1{2n}\sum f''(\eta_k)/n\)。其极限为 \(-\frac12\int_0^1f''(x)\,\mathrm dx=-1/2\)。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f C 1[0,1] )， (f(0)=0,f(1)=1 )。证明 [ n n [ 0 1f(x) , dx- 1n k=1 nf(k/n) ]=- 12. ] 极限为 (-1/2 )。 把积分按 (n ) 等分并与右端点 Riemann 和逐段相减，用中值定理写成 (- 1 2n f''( k)/n )。其极限为 (- 12 0 1f''(x) , dx=-1/2 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
