INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (97, 15, '5', 5, 'proof', 14.00, '设 \(f\) 在 \([0,1]\) 上连续，\(I=\int_0^1f(x)\,\mathrm dx\ne0\)。证明在 \((0,1)\) 内存在不同两点 \(x_1,x_2\)，使\n\[\frac1{f(x_1)}+\frac1{f(x_2)}=\frac2I.\]', '所述两点存在。', '令 \(F(x)=I^{-1}\int_0^xf(t)\,\mathrm dt\)。由介值定理取 \(\xi\) 使 \(F(\xi)=1/2\)。在 \([0,\xi]\)、\([\xi,1]\) 分别用 Lagrange 中值定理，所得两点分居两个区间，代数整理即得结论。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 上连续， (I= 0 1f(x) , dx 0 )。证明在 ((0,1) ) 内存在不同两点 (x 1,x 2 )，使 [ 1 f(x 1) + 1 f(x 2) = 2I. ] 所述两点存在。 令 (F(x)=I -1 0 xf(t) , dt )。由介值定理取 ( ) 使 (F( )=1/2 )。在 ([0, ] )、 ([ ,1] ) 分别用 Lagrange 中值定理，所得两点分居两个区间，代数整理即得结论。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
