INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (98, 15, '6', 6, 'proof', 14.00, '设 \(f\) 在实轴上可导，且 \(f(x)=f(x+2)=f(x+\sqrt3)\)。用 Fourier 级数证明 \(f\) 为常数。', '\(f(x)\) 为常数。', '把 \(f\) 作为周期 2 的函数展开。平移 \(\sqrt3\) 后不变，而 \(\sqrt3/2\) 为无理数，故所有非零频率的 Fourier 系数均只能为零。可导性保证级数处处收敛到 \(f\)，所以只剩常数项。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在实轴上可导，且 (f(x)=f(x+2)=f(x+ 3) )。用 Fourier 级数证明 (f ) 为常数。 (f(x) ) 为常数。 把 (f ) 作为周期 2 的函数展开。平移 ( 3 ) 后不变，而 ( 3/2 ) 为无理数，故所有非零频率的 Fourier 系数均只能为零。可导性保证级数处处收敛到 (f )，所以只剩常数项。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
