INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (101, 16, '3', 3, 'proof', 14.00, '设 \(f\) 是周期为 1 的连续函数，\(0\le f\le1\)，且 \(\int_0^1f=1\)。证明当 \(0\le x\le13\) 时，\n\[\int_0^xf(t)\,dt+\int_0^{\sqrt{x+27}}f(t)\,dt+\int_0^{\sqrt{13-x}}f(t)\,dt\le11,\]\n并给出取等号条件。', '最大值为 \(11\)，当且仅当 \(x=9\) 取等号。', '由 \(0\le f\le1\)，三项不超过 \(x+\sqrt{x+27}+\sqrt{13-x}\)。Cauchy 不等式给出该和不超过 11，等号要求 \(x=9\)。此时三个上限为 \(9,6,2\)，由周期性及单位周期积分为 1，三项之和确为 11。', '2017 年第八届全国大学生数学竞赛决赛（非数学类） 设 (f ) 是周期为 1 的连续函数， (0 f 1 )，且 ( 0 1f=1 )。证明当 (0 x 13 ) 时， [ 0 xf(t) ,dt+ 0 x+27 f(t) ,dt+ 0 13-x f(t) ,dt 11, ] 并给出取等号条件。 最大值为 (11 )，当且仅当 (x=9 ) 取等号。 由 (0 f 1 )，三项不超过 (x+ x+27 + 13-x )。Cauchy 不等式给出该和不超过 11，等号要求 (x=9 )。此时三个上限为 (9,6,2 )，由周期性及单位周期积分为 1，三项之和确为 11。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
