INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (104, 16, '6', 6, 'comprehensive', 14.00, '设 \(a_n=\sum_{k=1}^n1/k-\ln n\)。\n\n1. 证明 \(\lim a_n\) 存在；\n2. 记极限为 \(C\)，讨论 \(\sum_{n=1}^{\infty}(a_n-C)\) 的敛散性。', '1. 极限存在。 2. 级数发散。', '1. 用 \(x/(1+x)<\ln(1+x)<x\) 证明 \(a_n\) 单调递减且有下界。\n2. \(a_n-C\) 是收敛级数 \(a_n\) 对应的尾和。Taylor 估计给出 \(a_n-C\sim1/(2n)\)，故正项级数与调和级数同阶而发散。', '2017 年第八届全国大学生数学竞赛决赛（非数学类） 设 (a n= k=1 n1/k- n )。 1. 证明 ( a n ) 存在； 2. 记极限为 (C )，讨论 ( n=1 (a n-C) ) 的敛散性。 1. 极限存在。 2. 级数发散。 1. 用 (x/(1+x)< (1+x)<x ) 证明 (a n ) 单调递减且有下界。 2. (a n-C ) 是收敛级数 (a n ) 对应的尾和。Taylor 估计给出 (a n-C 1/(2n) )，故正项级数与调和级数同阶而发散。', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
