INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (83, 13, '3', 3, 'proof', 12.00, '设 \(f\) 在 \((a,b)\) 内二次可导，且存在常数 \(\alpha,\beta\)，使对任意 \(x\in(a,b)\) 有\n\[f''(x)=\alpha f(x)+\beta f''''(x).\]\n证明 \(f\) 在 \((a,b)\) 内无穷次可导。', '\(f\in C^\infty(a,b)\)。', '若 \(\beta=0\)，则 \(f''=\alpha f\)，逐次求导即可。若 \(\beta\ne0\)，则\n\[f''''=\beta^{-1}f''-\alpha\beta^{-1}f.\]\n右端可导，故 \(f''''''\) 存在；反复使用同一线性关系归纳，得到任意阶导数均存在。', '2015 年第七届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ((a,b) ) 内二次可导，且存在常数 ( , )，使对任意 (x (a,b) ) 有 [f''(x)= f(x)+ f''''(x). ] 证明 (f ) 在 ((a,b) ) 内无穷次可导。 (f C (a,b) )。 若 ( =0 )，则 (f''= f )，逐次求导即可。若 ( 0 )，则 [f''''= -1 f''- -1 f. ] 右端可导，故 (f'''''' ) 存在；反复使用同一线性关系归纳，得到任意阶导数均存在。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
