INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (70, 11, '2', 2, 'calculation', 12.00, '设 \(n\) 为正整数，计算\n\[I=\int_{e^{-2n\pi}}^1\left|\frac{\mathrm d}{\mathrm dx}\cos\!\left(\ln\frac1x\right)\right|\,\mathrm dx.\]', '\(I=4n\)。', '被积函数化为 \(|\sin(\ln x)|/x\)。令 \(u=\ln x\)，得\n\[I=\int_{-2n\pi}^0|\sin u|\,\mathrm du=4n.\]', '2014 年第六届全国大学生数学竞赛初赛（非数学类） 设 (n ) 为正整数，计算 [I= e -2n 1 | d dx ! ( 1x ) | , dx. ] (I=4n )。 被积函数化为 (| ( x)|/x )。令 (u= x )，得 [I= -2n 0| u| , du=4n. ]', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
