INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (71, 11, '3', 3, 'proof', 14.00, '设 \(f\) 在 \([0,1]\) 上有二阶导数，且存在正常数 \(A,B\) 使 \(|f(x)|\le A\)、\(|f''''(x)|\le B\)。证明对任意 \(x\in[0,1]\)，有\n\[|f''(x)|\le2A+\frac B2.\]', '\(\displaystyle|f''(x)|\le2A+B/2\)。', '分别在 \(x\) 点对 \(f(0)\)、\(f(1)\) 使用二阶 Taylor 公式并相减，得\n\[f''(x)=f(1)-f(0)-\frac12f''''(\eta)(1-x)^2+\frac12f''''(\xi)x^2.\]\n取绝对值并用 \((1-x)^2+x^2\le1\)，即得结论。', '2014 年第六届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 上有二阶导数，且存在正常数 (A,B ) 使 (|f(x)| A )、 (|f''''(x)| B )。证明对任意 (x [0,1] )，有 [|f''(x)| 2A+ B2. ] ( |f''(x)| 2A+B/2 )。 分别在 (x ) 点对 (f(0) )、 (f(1) ) 使用二阶 Taylor 公式并相减，得 [f''(x)=f(1)-f(0)- 12f''''( )(1-x) 2+ 12f''''( )x 2. ] 取绝对值并用 ((1-x) 2+x 2 1 )，即得结论。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
