INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (72, 11, '4', 4, 'comprehensive', 14.00, '1. 设球缺高为 \(h\)，所在球半径为 \(R\)。证明球缺体积为 \(\displaystyle\frac\pi3(3R-h)h^2\)，球冠面积为 \(2\pi Rh\)。\n2. 球体 \((x-1)^2+(y-1)^2+(z-1)^2\le12\) 被平面 \(x+y+z=6\) 截下的小球缺为 \(\Omega\)，球冠为 \(\Sigma\)，方向朝球外。求\n\[I=\iint_\Sigma x\,\mathrm dy\,\mathrm dz+y\,\mathrm dz\,\mathrm dx+z\,\mathrm dx\,\mathrm dy.\]', '1. \(V=\dfrac\pi3(3R-h)h^2\)，\(S=2\pi Rh\)。\n2. \(I=33\sqrt3\pi\)。', '1. 取球心为原点、球缺沿 \(z\) 轴，积分 \(z\in[R-h,R]\) 的圆截面面积即得体积；球坐标积分球面微元得球冠面积。\n\n2. 球半径为 \(2\sqrt3\)，球缺高为 \(\sqrt3\)。以底面圆补成闭曲面，用 Gauss 公式：\(I+J=3V\)。底面外法向量与 \((1,1,1)\) 反向，故 \(J=-2\sqrt3\,S_{\rm base}\)。代入球缺体积和底面积得 \(I=33\sqrt3\pi\)。', '2014 年第六届全国大学生数学竞赛初赛（非数学类） 1. 设球缺高为 (h )，所在球半径为 (R )。证明球缺体积为 ( 3(3R-h)h 2 )，球冠面积为 (2 Rh )。 2. 球体 ((x-1) 2+(y-1) 2+(z-1) 2 12 ) 被平面 (x+y+z=6 ) 截下的小球缺为 ( )，球冠为 ( )，方向朝球外。求 [I= x , dy , dz+y , dz , dx+z , dx , dy. ] 1. (V= 3(3R-h)h 2 )， (S=2 Rh )。 2. (I=33 3 )。 1. 取球心为原点、球缺沿 (z ) 轴，积分 (z [R-h,R] ) 的圆截面面积即得体积；球坐标积分球面微元得球冠面积。 2. 球半径为 (2 3 )，球缺高为 ( 3 )。以底面圆补成闭曲面，用 Gauss 公式： (I+J=3V )。底面外法向量与 ((1,1,1) ) 反向，故 (J=-2 3 ,S base )。代入球缺体积和底面积得 (I=33 3 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
