INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (73, 11, '5', 5, 'proof', 15.00, '设 \(f\) 在 \([a,b]\) 上非负连续、严格递增，且存在 \(x_n\in[a,b]\) 使\n\[[f(x_n)]^n=\frac1{b-a}\int_a^b[f(x)]^n\,\mathrm dx.\]\n求 \(\lim_{n\to\infty}x_n\)。', '\(\displaystyle\lim_{n\to\infty}x_n=b\)。', '先归一化到 \([0,1]\)。任取 \(\varepsilon>0\)，取 \(c\in(1-\varepsilon,1)\)，则\n\[f^n(x_n)=\int_0^1f^n(x)\,\mathrm dx\ge(1-c)f^n(c).\]\n因 \(f(1-\varepsilon)/f(c)<1\)，充分大的 \(n\) 有 \(f(x_n)>f(1-\varepsilon)\)，故 \(x_n>1-\varepsilon\)。还原线性变换即得极限 \(b\)。', '2014 年第六届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([a,b] ) 上非负连续、严格递增，且存在 (x n [a,b] ) 使 [[f(x n)] n= 1 b-a a b[f(x)] n , dx. ] 求 ( n x n )。 ( n x n=b )。 先归一化到 ([0,1] )。任取 ( >0 )，取 (c (1- ,1) )，则 [f n(x n)= 0 1f n(x) , dx (1-c)f n(c). ] 因 (f(1- )/f(c)<1 )，充分大的 (n ) 有 (f(x n)>f(1- ) )，故 (x n>1- )。还原线性变换即得极限 (b )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
