INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (76, 12, '2', 2, 'proof', 12.00, '设 \(\boldsymbol l_j\ (j=1,\ldots,n)\) 是平面上点 \(P_0\) 处的 \(n\ge2\) 个单位方向向量，相邻两向量夹角为 \(2\pi/n\)。若 \(f(x,y)\) 在 \(P_0\) 有连续偏导数，证明\n\[\sum_{j=1}^n\frac{\partial f(P_0)}{\partial\boldsymbol l_j}=0.\]', '所给方向导数之和为 \(0\)。', '由方向导数公式，\n\[\sum_{j=1}^n\frac{\partial f(P_0)}{\partial\boldsymbol l_j}=\nabla f(P_0)\cdot\sum_{j=1}^n\boldsymbol l_j.\]\n这些等角方向向量是正 \(n\) 边形的径向量，向量和为零，故结论成立。', '2015 年第六届全国大学生数学竞赛决赛（非数学类） 设 ( l j (j=1, ,n) ) 是平面上点 (P 0 ) 处的 (n 2 ) 个单位方向向量，相邻两向量夹角为 (2 /n )。若 (f(x,y) ) 在 (P 0 ) 有连续偏导数，证明 [ j=1 n f(P 0) l j =0. ] 所给方向导数之和为 (0 )。 由方向导数公式， [ j=1 n f(P 0) l j = f(P 0) j=1 n l j. ] 这些等角方向向量是正 (n ) 边形的径向量，向量和为零，故结论成立。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
