INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (58, 9, '4', 4, 'proof', 10.00, '设 \(|f(x)|\le\pi\)、\(f''(x)\ge m>0\ (a\le x\le b)\)。证明\n\[\left|\int_a^b\sin f(x)\,\mathrm dx\right|\le\frac2m.\]', '\(\displaystyle\left|\int_a^b\sin f(x)\,\mathrm dx\right|\le2/m\)。', '函数 \(f\) 严格递增并有反函数 \(x=\varphi(y)\)，且 \(0<\varphi''(y)\le1/m\)。令 \(A=f(a),B=f(b)\)，则 \(-\pi\le A<B\le\pi\)，从而\n\[\left|\int_A^B\varphi''(y)\sin y\,\mathrm dy\right|\le\frac1m\int_{-\pi}^{\pi}|\sin y|\,\mathrm dy\le\frac2m.\]\n按正负区间分别估计可得所需更紧的上界 \(2/m\)。', '2013 年第五届全国大学生数学竞赛初赛（非数学类） 设 (|f(x)| )、 (f''(x) m>0 (a x b) )。证明 [ | a b f(x) , dx | 2m. ] ( | a b f(x) , dx | 2/m )。 函数 (f ) 严格递增并有反函数 (x= (y) )，且 (0< ''(y) 1/m )。令 (A=f(a),B=f(b) )，则 (- A<B )，从而 [ | A B ''(y) y , dy | 1m - | y| , dy 2m. ] 按正负区间分别估计可得所需更紧的上界 (2/m )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
