INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (60, 9, '6', 6, 'calculation', 14.00, '设\n\[I_a(r)=\oint_C\frac{y\,\mathrm dx-x\,\mathrm dy}{(x^2+y^2)^a},\]\n其中 \(a\) 为常数，\(C:x^2+xy+y^2=r^2\) 取正向。求 \(\displaystyle\lim_{r\to+\infty}I_a(r)\)。', '\[\lim_{r\to+\infty}I_a(r)=\begin{cases}0,&a>1,\\-2\pi,&a=1,\\-\infty,&a<1.\end{cases}\]', '令 \(x=(u-v)/\sqrt2,y=(u+v)/\sqrt2\)，再将椭圆参数化，可得\n\[I_a(r)=-\frac{2r^{2(1-a)}}3J_a,\qquad J_a=\int_0^{2\pi}\frac{\mathrm d\theta}{(\frac23\cos^2\theta+2\sin^2\theta)^a}>0.\]\n当 \(a=1\) 时 \(J_1=3\pi\)。按 \(r^{2(1-a)}\) 的极限即得结论。', '2013 年第五届全国大学生数学竞赛初赛（非数学类） 设 [I a(r)= C y , dx-x , dy (x 2+y 2) a , ] 其中 (a ) 为常数， (C:x 2+xy+y 2=r 2 ) 取正向。求 ( r + I a(r) )。 [ r + I a(r)= cases 0,&a>1, -2 ,&a=1, - ,&a<1. cases ] 令 (x=(u-v)/ 2,y=(u+v)/ 2 )，再将椭圆参数化，可得 [I a(r)=- 2r 2(1-a) 3J a, J a= 0 2 d ( 23 2 +2 2 ) a >0. ] 当 (a=1 ) 时 (J 1=3 )。按 (r 2(1-a) ) 的极限即得结论。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
