INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (63, 10, '2', 2, 'proof', 12.00, '设 \(f\in C^4(-\infty,+\infty)\)，且\n\[f(x+h)=f(x)+f''(x)h+\frac12f''''(x+\theta h)h^2,\]\n其中 \(\theta\) 是与 \(x,h\) 无关的常数。证明 \(f\) 是不超过三次的多项式。', '\(f\) 是次数不超过三次的多项式。', '分别将等式两边作四阶 Taylor 展开并比较，得到\n\[4(1-3\theta)f''''''(x)=[6\theta^2f^{(4)}(\eta)-f^{(4)}(\xi)]h.\]\n若 \(\theta\ne1/3\)，令 \(h\to0\) 得 \(f''''''=0\)；若 \(\theta=1/3\)，再比较四阶项得 \(f^{(4)}=0\)。故 \(f\) 至多三次。', '2014 年第五届全国大学生数学竞赛决赛（非数学类） 设 (f C 4(- ,+ ) )，且 [f(x+h)=f(x)+f''(x)h+ 12f''''(x+ h)h 2, ] 其中 ( ) 是与 (x,h ) 无关的常数。证明 (f ) 是不超过三次的多项式。 (f ) 是次数不超过三次的多项式。 分别将等式两边作四阶 Taylor 展开并比较，得到 [4(1-3 )f''''''(x)=[6 2f (4) ( )-f (4) ( )]h. ] 若 ( 1/3 )，令 (h 0 ) 得 (f''''''=0 )；若 ( =1/3 )，再比较四阶项得 (f (4) =0 )。故 (f ) 至多三次。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
