INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (65, 10, '4', 4, 'proof', 10.00, '设 \(D=[0,1]\times[0,1]\)，\(I=\iint_Df(x,y)\,\mathrm dx\,\mathrm dy\)。函数 \(f\) 在 \(D\) 上有连续二阶偏导数，且 \(f(0,y)=f(x,0)=0\)、\(f_{xy}\le A\)。证明 \(I\le A/4\)。', '\(I\le A/4\)。', '由边界条件连续两次分部积分，\n\[I=\iint_D(1-x)(1-y)f_{xy}(x,y)\,\mathrm dx\,\mathrm dy.\]\n因权函数非负且 \(f_{xy}\le A\)，故\n\[I\le A\int_0^1(1-x)\,\mathrm dx\int_0^1(1-y)\,\mathrm dy=\frac A4.\]', '2014 年第五届全国大学生数学竞赛决赛（非数学类） 设 (D=[0,1] [0,1] )， (I= Df(x,y) , dx , dy )。函数 (f ) 在 (D ) 上有连续二阶偏导数，且 (f(0,y)=f(x,0)=0 )、 (f xy A )。证明 (I A/4 )。 (I A/4 )。 由边界条件连续两次分部积分， [I= D(1-x)(1-y)f xy (x,y) , dx , dy. ] 因权函数非负且 (f xy A )，故 [I A 0 1(1-x) , dx 0 1(1-y) , dy= A4. ]', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
