INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (66, 10, '5', 5, 'calculation', 12.00, '设 \(P=Q=R=f((x^2+y^2)z)\)，\(\Sigma_t\) 是圆柱体 \(x^2+y^2\le t^2,0\le z\le1\) 的外表面。记\n\[I_t=\iint_{\Sigma_t}P\,\mathrm dy\,\mathrm dz+Q\,\mathrm dz\,\mathrm dx+R\,\mathrm dx\,\mathrm dy.\]\n求 \(\displaystyle\lim_{t\to0^+}I_t/t^4\)。', '\(\displaystyle\frac\pi2f''(0)\)。', '由 Gauss 公式及对称性，含 \(xz,yz\) 的项积分为零，故\n\[I_t=2\pi\int_0^1\int_0^t f''(r^2z)r^3\,\mathrm dr\,\mathrm dz.\]\n除以 \(t^4\) 后令 \(t\to0^+\)，连续性给出极限 \(\frac\pi2f''(0)\)。', '2014 年第五届全国大学生数学竞赛决赛（非数学类） 设 (P=Q=R=f((x 2+y 2)z) )， ( t ) 是圆柱体 (x 2+y 2 t 2,0 z 1 ) 的外表面。记 [I t= t P , dy , dz+Q , dz , dx+R , dx , dy. ] 求 ( t 0 + I t/t 4 )。 ( 2f''(0) )。 由 Gauss 公式及对称性，含 (xz,yz ) 的项积分为零，故 [I t=2 0 1 0 t f''(r 2z)r 3 , dr , dz. ] 除以 (t 4 ) 后令 (t 0 + )，连续性给出极限 ( 2f''(0) )。', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
