INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (44, 7, '3', 3, 'calculation', 10.00, '求方程 \(x^2\sin(1/x)=2x-501\) 的近似解，精确到 \(0.001\)。', '\(x\approx501.000\)。', '由 Taylor 公式 \(\sin(1/x)=1/x-\sin(\theta/x)/(2x^2)\)，方程化为 \(x=501-\frac12\sin(\theta/x)\)。可知 \(x>500\)，故 \(|x-501|<1/(2x)<0.001\)。', '2012 年第四届全国大学生数学竞赛初赛（非数学类） 求方程 (x 2 (1/x)=2x-501 ) 的近似解，精确到 (0.001 )。 (x 501.000 )。 由 Taylor 公式 ( (1/x)=1/x- ( /x)/(2x 2) )，方程化为 (x=501- 12 ( /x) )。可知 (x>500 )，故 (|x-501|<1/(2x)<0.001 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
