INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (52, 8, '4', 4, 'proof', 15.00, '设 \(f\) 在 \([-2,2]\) 上二阶可导，\(|f(x)|<1\)，且 \(f^2(0)+[f''(0)]^2=4\)。证明：存在 \(\xi\in(-2,2)\)，使 \(f(\xi)+f''''(\xi)=0\)。', '存在所述 \(\xi\)。', '在 \([-2,0]\)、\([0,2]\) 使用中值定理，分别得两点使 \(|f''|<1\)。令 \(H=f^2+(f'')^2\)，两点处 \(H<2\)，而 \(H(0)=4\)。故 \(H\) 在两点之间的最大值于内部 \(\xi\) 取得，且 \(H''(\xi)=2f''(\xi)[f(\xi)+f''''(\xi)]=0\)。又 \(|f(\xi)|<1\)、\(H(\xi)\ge4\)，故 \(f''(\xi)\ne0\)，结论成立。', '2013 年第四届全国大学生数学竞赛决赛（非数学类） 设 (f ) 在 ([-2,2] ) 上二阶可导， (|f(x)|<1 )，且 (f 2(0)+[f''(0)] 2=4 )。证明：存在 ( (-2,2) )，使 (f( )+f''''( )=0 )。 存在所述 ( )。 在 ([-2,0] )、 ([0,2] ) 使用中值定理，分别得两点使 (|f''|<1 )。令 (H=f 2+(f'') 2 )，两点处 (H<2 )，而 (H(0)=4 )。故 (H ) 在两点之间的最大值于内部 ( ) 取得，且 (H''( )=2f''( )[f( )+f''''( )]=0 )。又 (|f( )|<1 )、 (H( ) 4 )，故 (f''( ) 0 )，结论成立。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
