INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (54, 8, '6', 6, 'proof', 15.00, '若对任何收敛到 0 的数列 \(\{x_n\}\)，级数 \(\sum_{n=1}^\infty a_nx_n\) 都收敛，证明 \(\sum_{n=1}^\infty|a_n|\) 收敛。', '\(\sum|a_n|\) 收敛。', '反证。若 \(\sum|a_n|=\infty\)，可取递增分块端点 \(m_k\)，使第 \(k\) 块的绝对值和至少为 \(k\)。在第 \(k\) 块令 \(x_i=\operatorname{sgn}(a_i)/k\)，则 \(x_i\to0\)，但每块 \(\sum a_ix_i\ge1\)，故级数不能收敛，与题设矛盾。', '2013 年第四届全国大学生数学竞赛决赛（非数学类） 若对任何收敛到 0 的数列 ( x n )，级数 ( n=1 a nx n ) 都收敛，证明 ( n=1 |a n| ) 收敛。 ( |a n| ) 收敛。 反证。若 ( |a n|= )，可取递增分块端点 (m k )，使第 (k ) 块的绝对值和至少为 (k )。在第 (k ) 块令 (x i= sgn (a i)/k )，则 (x i 0 )，但每块 ( a ix i 1 )，故级数不能收敛，与题设矛盾。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
