INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (33, 5, '4', 4, 'calculation', 15.00, '平面上有一条从 \((a,0)\) 向右的射线，线密度为 \(\rho\)。在 \((0,h)\) 处（\(h>0\)）有质量为 \(m\) 的质点。求射线对该质点的引力（引力常数为 \(G\)）。', '\[\boldsymbol F=\left(\frac{Gm\rho}{\sqrt{a^2+h^2}},\ -\frac{Gm\rho}{h}\left(1-\frac{a}{\sqrt{a^2+h^2}}\right)\right).\]', '射线上 \((x,0)\) 处质量元为 \(\rho\,\mathrm dx\)，其引力沿 \((x,-h)\) 方向。分解并积分 \(x\in[a,\infty)\)：\n\[F_x=Gm\rho\int_a^\infty\frac{x\,\mathrm dx}{(x^2+h^2)^{3/2}}=\frac{Gm\rho}{\sqrt{a^2+h^2}},\]\n\[F_y=-Gm\rho h\int_a^\infty\frac{\mathrm dx}{(x^2+h^2)^{3/2}}=-\frac{Gm\rho}{h}\left(1-\frac{a}{\sqrt{a^2+h^2}}\right).\]', '2011 年第三届全国大学生数学竞赛初赛（非数学类） 平面上有一条从 ((a,0) ) 向右的射线，线密度为 ( )。在 ((0,h) ) 处（ (h>0 )）有质量为 (m ) 的质点。求射线对该质点的引力（引力常数为 (G )）。 [ F= ( Gm a 2+h 2 , - Gm h (1- a a 2+h 2 ) ). ] 射线上 ((x,0) ) 处质量元为 ( , dx )，其引力沿 ((x,-h) ) 方向。分解并积分 (x [a, ) )： [F x=Gm a x , dx (x 2+h 2) 3/2 = Gm a 2+h 2 , ] [F y=-Gm h a dx (x 2+h 2) 3/2 =- Gm h (1- a a 2+h 2 ). ]', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
