INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (37, 6, '2', 2, 'calculation', 13.00, '讨论 \(\int_0^{+\infty}\frac{x\,\mathrm dx}{\cos^2x+x^\alpha\sin^2x}\) 的敛散性，其中 \(\alpha\in\mathbb R\)。', '当且仅当 \(\alpha>4\) 时收敛；\(\alpha\le4\) 时发散。', '零点附近被积函数可积，只需考察无穷远。按区间 \([n\pi,(n+1)\pi]\) 分块，并使用\n\[\int_0^\pi\frac{\mathrm dx}{1+b\sin^2x}=\frac\pi{\sqrt{1+b}},\]\n可得第 \(n\) 块积分与 \(n^{1-\alpha/2}\) 同阶。因此对应级数当且仅当 \(1-\alpha/2<-1\)，即 \(\alpha>4\) 时收敛。', '2012 年第三届全国大学生数学竞赛决赛（非数学专业） 讨论 ( 0 + x , dx 2x+x 2x ) 的敛散性，其中 ( R )。 当且仅当 ( >4 ) 时收敛； ( 4 ) 时发散。 零点附近被积函数可积，只需考察无穷远。按区间 ([n ,(n+1) ] ) 分块，并使用 [ 0 dx 1+b 2x = 1+b , ] 可得第 (n ) 块积分与 (n 1- /2 ) 同阶。因此对应级数当且仅当 (1- /2<-1 )，即 ( >4 ) 时收敛。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
