INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (39, 6, '4', 4, 'comprehensive', 16.00, '设 \(D:x^2/a^2+y^2/b^2\le1\ (a>b>0)\) 为面密度 \(\rho\) 的均质椭圆薄板；\(l\) 为通过焦点 \((-c,0)\)、垂直薄板的轴，其中 \(c^2=a^2-b^2\)。\n1. 求转动惯量 \(J\)；2. 对固定 \(J\)，讨论薄板面积是否有最大值和最小值。', '\[J=\frac{ab\pi\rho}{4}(5a^2-3b^2).\]\n固定 \(J\) 时面积既无最大值也无最小值，且 \(0<S<\sqrt{2\pi J/\rho}\)。', '作变换 \(x=ar\cos\theta,y=br\sin\theta\)，对到轴的距离平方 \((x+c)^2+y^2\) 积分，得所列 \(J\)。固定 \(J\) 后把 \(b\) 看作 \(a\) 的隐函数，考察 \(S=\pi ab\)。当 \(b\to a^-\) 时 \(S\to\sqrt{2\pi J/\rho}\) 但不取到；当 \(a\to\infty\) 时 \(b=O(a^{-3})\)，故 \(S\to0\) 但不取到。因此无最大、最小值。', '2012 年第三届全国大学生数学竞赛决赛（非数学专业） 设 (D:x 2/a 2+y 2/b 2 1 (a>b>0) ) 为面密度 ( ) 的均质椭圆薄板； (l ) 为通过焦点 ((-c,0) )、垂直薄板的轴，其中 (c 2=a 2-b 2 )。 1. 求转动惯量 (J )；2. 对固定 (J )，讨论薄板面积是否有最大值和最小值。 [J= ab 4 (5a 2-3b 2). ] 固定 (J ) 时面积既无最大值也无最小值，且 (0<S< 2 J/ )。 作变换 (x=ar ,y=br )，对到轴的距离平方 ((x+c) 2+y 2 ) 积分，得所列 (J )。固定 (J ) 后把 (b ) 看作 (a ) 的隐函数，考察 (S= ab )。当 (b a - ) 时 (S 2 J/ ) 但不取到；当 (a ) 时 (b=O(a -3 ) )，故 (S 0 ) 但不取到。因此无最大、最小值。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
