INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (40, 6, '5', 5, 'calculation', 12.00, '设连续可微函数 \(z=z(x,y)\) 由 \(F(xz-y,x-yz)=0\) 唯一确定，\(L\) 为正向单位圆周，求\n\[I=\oint_L(xz^2+2yz)\,\mathrm dy-(2xz+yz^2)\,\mathrm dx.\]', '\(I=2\pi\)。', '令 \(Q=xz^2+2yz\)、\(P=-(2xz+yz^2)\)。由隐式方程分别求导，可化出\n\[(xz+y)z_x+(x+yz)z_y=1-z^2.\]\n使用 Green 公式，\(Q_x-P_y=2[(xz+y)z_x+(x+yz)z_y+z^2]=2\)，故\n\[I=2\iint_{x^2+y^2\le1}\mathrm dx\,\mathrm dy=2\pi.\]', '2012 年第三届全国大学生数学竞赛决赛（非数学专业） 设连续可微函数 (z=z(x,y) ) 由 (F(xz-y,x-yz)=0 ) 唯一确定， (L ) 为正向单位圆周，求 [I= L(xz 2+2yz) , dy-(2xz+yz 2) , dx. ] (I=2 )。 令 (Q=xz 2+2yz )、 (P=-(2xz+yz 2) )。由隐式方程分别求导，可化出 [(xz+y)z x+(x+yz)z y=1-z 2. ] 使用 Green 公式， (Q x-P y=2[(xz+y)z x+(x+yz)z y+z 2]=2 )，故 [I=2 x 2+y 2 1 dx , dy=2 . ]', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
