INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (41, 6, '6', 6, 'comprehensive', 16.00, '1. 解初值问题 \(y''-xy=xe^{x^2},\ y(0)=1\)。\n2. 若 \(y=f(x)\) 为其解，证明 \(\lim_{n\to\infty}\int_0^1\frac{nf(x)}{n^2x^2+1}\,\mathrm dx=\pi/2\)。', '1. \(y=e^{x^2}\)。 2. 极限为 \(\pi/2\)。', '1. 线性方程积分因子为 \(e^{-x^2/2}\)，代入初值得 \(y=e^{x^2}\)。\n2. 分解 \(e^{x^2}=1+(e^{x^2}-1)\)。第一项积分为 \(\arctan n\to\pi/2\)。对第二项，在 \([0,\delta]\) 用 \(e^{x^2}-1\to0\) 控制，在 \([\delta,1]\) 用分母的 \(n^2x^2\) 控制，故该项趋于 0。', '2012 年第三届全国大学生数学竞赛决赛（非数学专业） 1. 解初值问题 (y''-xy=xe x 2 , y(0)=1 )。 2. 若 (y=f(x) ) 为其解，证明 ( n 0 1 nf(x) n 2x 2+1 , dx= /2 )。 1. (y=e x 2 )。 2. 极限为 ( /2 )。 1. 线性方程积分因子为 (e -x 2/2 )，代入初值得 (y=e x 2 )。 2. 分解 (e x 2 =1+(e x 2 -1) )。第一项积分为 ( n /2 )。对第二项，在 ([0, ] ) 用 (e x 2 -1 0 ) 控制，在 ([ ,1] ) 用分母的 (n 2x 2 ) 控制，故该项趋于 0。', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
