INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (18, 3, '2', 2, 'proof', 15.00, '设函数 \(f(x)\) 在 \(( -\infty,+\infty)\) 上具有二阶导数，并且\n\[f''''(x)>0,\qquad \lim_{x\to+\infty}f''(x)=\alpha>0,\qquad \lim_{x\to-\infty}f''(x)=\beta<0.\]\n且存在一点 \(x_0\)，使得 \(f(x_0)<0\)。证明：方程 \(f(x)=0\) 在 \(( -\infty,+\infty)\) 内恰有两个实根。', '方程 \(f(x)=0\) 在 \(( -\infty,+\infty)\) 内恰有两个实根。', '因 \(\lim_{x\to+\infty}f''(x)=\alpha>0\)，可取 \(a>x_0\) 使 \(f''(a)>0\)。由 \(f''''>0\)，\n\[f(x)>f(a)+f''(a)(x-a)\quad(x>a),\]\n故充分大的 \(b>a\) 满足 \(f(b)>0\)。同理，由 \(\lim_{x\to-\infty}f''(x)=\beta<0\)，可取充分小的 \(c<x_0\) 使 \(f''(c)<0\)，再取 \(d<c\) 得 \(f(d)>0\)。结合 \(f(x_0)<0\)，零点定理保证 \((d,x_0)\) 与 \((x_0,b)\) 各有一根。\n\n若有三个根 \(x_1<x_2<x_3\)，对相邻区间两次使用罗尔定理，可得某点 \(\eta\) 满足 \(f''''(\eta)=0\)，与 \(f''''>0\) 矛盾。因此恰有两个实根。', '2010 年第二届全国大学生数学竞赛初赛（非数学类） 设函数 (f(x) ) 在 (( - ,+ ) ) 上具有二阶导数，并且 [f''''(x)>0, x + f''(x)= >0, x - f''(x)= <0. ] 且存在一点 (x 0 )，使得 (f(x 0)<0 )。证明：方程 (f(x)=0 ) 在 (( - ,+ ) ) 内恰有两个实根。 方程 (f(x)=0 ) 在 (( - ,+ ) ) 内恰有两个实根。 因 ( x + f''(x)= >0 )，可取 (a>x 0 ) 使 (f''(a)>0 )。由 (f''''>0 )， [f(x)>f(a)+f''(a)(x-a) (x>a), ] 故充分大的 (b>a ) 满足 (f(b)>0 )。同理，由 ( x - f''(x)= <0 )，可取充分小的 (c<x 0 ) 使 (f''(c)<0 )，再取 (d<c ) 得 (f(d)>0 )。结合 (f(x 0)<0 )，零点定理保证 ((d,x 0) ) 与 ((x 0,b) ) 各有一根。 若有三个根 (x 1<x 2<x 3 )，对相邻区间两次使用罗尔定理，可得某点 ( ) 满足 (f''''( )=0 )，与 (f''''>0 ) 矛盾。因此恰有两个实根。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
