INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (20, 3, '4', 4, 'proof', 15.00, '设 \(a_n>0\)，\(S_n=\sum_{k=1}^n a_k\)。证明：\n\n1. 当 \(\alpha>1\) 时，级数 \(\sum_{n=1}^{\infty}\frac{a_n}{S_n^\alpha}\) 收敛；\n2. 当 \(\alpha\le1\) 且 \(S_n\to\infty\) 时，级数 \(\sum_{n=1}^{\infty}\frac{a_n}{S_n^\alpha}\) 发散。', '当 \(\alpha>1\) 时收敛；当 \(\alpha\le1\) 且 \(S_n\to\infty\) 时发散。', '对 \(f(x)=x^{1-\alpha}\) 在 \([S_{n-1},S_n]\) 使用中值定理。\n\n当 \(\alpha>1\) 时，\n\[\frac1{S_{n-1}^{\alpha-1}}-\frac1{S_n^{\alpha-1}} \ge(\alpha-1)\frac{a_n}{S_n^\alpha}.\]\n右侧级数的部分和被望远镜和控制，故收敛。\n\n当 \(\alpha=1\) 且 \(S_n\to\infty\) 时，对任意固定 \(n\) 可取 \(p\) 使 \(S_n/S_{n+p}<1/2\)，于是\n\[\sum_{k=n+1}^{n+p}\frac{a_k}{S_k}\ge\frac{S_{n+p}-S_n}{S_{n+p}}>\frac12,\]\n不满足柯西准则。若 \(\alpha<1\)，对充分大的 \(n\) 有 \(S_n^\alpha\le S_n\)，再由比较判别法知发散。', '2010 年第二届全国大学生数学竞赛初赛（非数学类） 设 (a n>0 )， (S n= k=1 n a k )。证明： 1. 当 ( >1 ) 时，级数 ( n=1 a n S n ) 收敛； 2. 当 ( 1 ) 且 (S n ) 时，级数 ( n=1 a n S n ) 发散。 当 ( >1 ) 时收敛；当 ( 1 ) 且 (S n ) 时发散。 对 (f(x)=x 1- ) 在 ([S n-1 ,S n] ) 使用中值定理。 当 ( >1 ) 时， [ 1 S n-1 -1 - 1 S n -1 ( -1) a n S n . ] 右侧级数的部分和被望远镜和控制，故收敛。 当 ( =1 ) 且 (S n ) 时，对任意固定 (n ) 可取 (p ) 使 (S n/S n+p <1/2 )，于是 [ k=n+1 n+p a k S k S n+p -S n S n+p > 12, ] 不满足柯西准则。若 ( <1 )，对充分大的 (n ) 有 (S n S n )，再由比较判别法知发散。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
