INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (22, 3, '6', 6, 'comprehensive', 15.00, '设函数 \(\varphi(x)\) 具有连续导数。在围绕原点的任意光滑简单闭曲线 \(C\) 上，曲线积分\n\[\oint_C\frac{2xy\,\mathrm dx+\varphi(x)\,\mathrm dy}{x^4+y^2}\]\n的值为常数。\n\n1. 设 \(L\) 为正向闭曲线 \((x-2)^2+y^2=1\)，证明上述积分在 \(L\) 上为 0；\n2. 求 \(\varphi(x)\)；\n3. 设 \(C\) 是围绕原点的光滑简单正向闭曲线，求该积分。', '1. 积分为 \(0\)；2. \(\varphi(x)=-x^2\)；3. 积分为 \(0\)。', '1. 将 \(L\) 分成两段，并用一条不经过原点的辅助曲线分别与两段组成围绕原点的闭曲线。由题设两闭曲线积分相等，相减即得 \(L\) 上积分为 0。\n2. 记 \(P=\frac{2xy}{x^4+y^2}\)、\(Q=\frac{\varphi(x)}{x^4+y^2}\)。在不含原点的区域内由 Green 公式及闭路积分为零，必须有 \(P_y=Q_x\)，即\n   \[\frac{2x^5-2xy^2}{(x^4+y^2)^2} =\frac{\varphi''(x)(x^4+y^2)-4x^3\varphi(x)}{(x^4+y^2)^2}.\]\n   比较关于 \(y\) 的系数，得 \(\varphi(x)=-x^2\)。\n3. 取围绕原点的圆 \(C_a:x^4+y^2=1\) 与任意 \(C\) 比较，并在两曲线之间使用 Green 公式。因 \(\varphi=-x^2\) 且圆上的积分为零，故任意这样的 \(C\) 上积分均为 \(0\)。', '2010 年第二届全国大学生数学竞赛初赛（非数学类） 设函数 ( (x) ) 具有连续导数。在围绕原点的任意光滑简单闭曲线 (C ) 上，曲线积分 [ C 2xy , dx+ (x) , dy x 4+y 2 ] 的值为常数。 1. 设 (L ) 为正向闭曲线 ((x-2) 2+y 2=1 )，证明上述积分在 (L ) 上为 0； 2. 求 ( (x) )； 3. 设 (C ) 是围绕原点的光滑简单正向闭曲线，求该积分。 1. 积分为 (0 )；2. ( (x)=-x 2 )；3. 积分为 (0 )。 1. 将 (L ) 分成两段，并用一条不经过原点的辅助曲线分别与两段组成围绕原点的闭曲线。由题设两闭曲线积分相等，相减即得 (L ) 上积分为 0。 2. 记 (P= 2xy x 4+y 2 )、 (Q= (x) x 4+y 2 )。在不含原点的区域内由 Green 公式及闭路积分为零，必须有 (P y=Q x )，即 [ 2x 5-2xy 2 (x 4+y 2) 2 = ''(x)(x 4+y 2)-4x 3 (x) (x 4+y 2) 2 . ] 比较关于 (y ) 的系数，得 ( (x)=-x 2 )。 3. 取围绕原点的圆 (C a:x 4+y 2=1 ) 与任意 (C ) 比较，并在两曲线之间使用 Green 公式。因 ( =-x 2 ) 且圆上的积分为零，故任意这样的 (C ) 上积分均为 (0 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
