INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (2, 1, '2', 2, 'calculation', 5.00, '设 \(n\) 为给定的正整数，求极限\n\[\lim_{x\to0}\left(\frac{e^x+e^{2x}+\cdots+e^{nx}}{n}\right)^{e/x}\].', '\[e^{\frac{n+1}{2}e}\].', '取对数并用洛必达法则：\n\[\lim_{x\to0}\frac{e}{x}\ln\frac{e^x+e^{2x}+\cdots+e^{nx}}n =e\lim_{x\to0}\frac{e^x+2e^{2x}+\cdots+ne^{nx}}{e^x+e^{2x}+\cdots+e^{nx}} =\frac{n+1}{2}e.\]\n故原极限为 \(e^{\frac{n+1}{2}e}\)。', '2009 年第一届全国大学生数学竞赛初赛（非数学类） 设 (n ) 为给定的正整数，求极限 [ x 0 ( e x+e 2x + +e nx n ) e/x ]. [e n+1 2 e ]. 取对数并用洛必达法则： [ x 0 e x e x+e 2x + +e nx n =e x 0 e x+2e 2x + +ne nx e x+e 2x + +e nx = n+1 2 e. ] 故原极限为 (e n+1 2 e )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
