INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (3, 1, '3', 3, 'comprehensive', 15.00, '设函数 \(f(x)\) 连续，\n\[g(x)=\int_0^1f(xt)\,\mathrm dt,\]\n且 \(\lim_{x\to0}\frac{f(x)}x=A\)，其中 \(A\) 为常数。求 \(g''(x)\)，并讨论 \(g''(x)\) 在 \(x=0\) 处的连续性。', '当 \(x\ne0\) 时，\n\[g''(x)=\frac{xf(x)-\int_0^x f(u)\,\mathrm du}{x^2}.\]\n且 \(g''(0)=\frac A2\)，\(g''\) 在 \(x=0\) 处连续。', '由已知极限知 \(f(0)=0\)。令 \(u=xt\)，当 \(x\ne0\) 时\n\[g(x)=\frac1x\int_0^x f(u)\,\mathrm du,\]\n故\n\[g''(x)=\frac{xf(x)-\int_0^x f(u)\,\mathrm du}{x^2}.\]\n由导数定义和洛必达法则，\n\[g''(0)=\lim_{x\to0}\frac{\int_0^x f(u)\,\mathrm du}{x^2}=\frac A2.\]\n又\n\[\lim_{x\to0}g''(x)=A-\frac A2=\frac A2=g''(0),\]\n所以 \(g''\) 在 \(0\) 处连续。', '2009 年第一届全国大学生数学竞赛初赛（非数学类） 设函数 (f(x) ) 连续， [g(x)= 0 1f(xt) , dt, ] 且 ( x 0 f(x) x=A )，其中 (A ) 为常数。求 (g''(x) )，并讨论 (g''(x) ) 在 (x=0 ) 处的连续性。 当 (x 0 ) 时， [g''(x)= xf(x)- 0 x f(u) , du x 2 . ] 且 (g''(0)= A2 )， (g'' ) 在 (x=0 ) 处连续。 由已知极限知 (f(0)=0 )。令 (u=xt )，当 (x 0 ) 时 [g(x)= 1x 0 x f(u) , du, ] 故 [g''(x)= xf(x)- 0 x f(u) , du x 2 . ] 由导数定义和洛必达法则， [g''(0)= x 0 0 x f(u) , du x 2 = A2. ] 又 [ x 0 g''(x)=A- A2= A2=g''(0), ] 所以 (g'' ) 在 (0 ) 处连续。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
