INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (7, 1, '7', 7, 'calculation', 15.00, '已知 \(u_n(x)\) 满足\n\[u_n''(x)=u_n(x)+x^{n-1}e^x\quad(n\text{ 为正整数}),\qquad u_n(1)=\frac en.\]\n求函数项级数 \(\sum_{n=1}^{\infty}u_n(x)\) 之和。', '当 \(-1\le x<1\) 时，\n\[\sum_{n=1}^{\infty}u_n(x)=-e^x\ln(1-x).\]', '解一阶线性方程得\n\[u_n(x)=e^x\left(\frac{x^n}{n}+C\right).\]\n由 \(u_n(1)=\frac en\) 得 \(C=0\)，故 \(u_n(x)=\frac{x^ne^x}{n}\)。于是\n\[\sum_{n=1}^{\infty}u_n(x)=e^x\sum_{n=1}^{\infty}\frac{x^n}{n}=-e^x\ln(1-x),\]\n收敛区间为 \(-1\le x<1\)。', '2009 年第一届全国大学生数学竞赛初赛（非数学类） 已知 (u n(x) ) 满足 [u n''(x)=u n(x)+x n-1 e x (n 为正整数 ), u n(1)= en. ] 求函数项级数 ( n=1 u n(x) ) 之和。 当 (-1 x<1 ) 时， [ n=1 u n(x)=-e x (1-x). ] 解一阶线性方程得 [u n(x)=e x ( x n n +C ). ] 由 (u n(1)= en ) 得 (C=0 )，故 (u n(x)= x ne x n )。于是 [ n=1 u n(x)=e x n=1 x n n =-e x (1-x), ] 收敛区间为 (-1 x<1 )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO question_knowledge_points (question_id, knowledge_point_id, is_primary) VALUES (7, 39, TRUE) ON CONFLICT DO NOTHING;
