INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (10, 2, '2', 2, 'calculation', 10.00, '求下列极限：\n\n1. \[\lim_{n\to\infty}n\left[\left(1+\frac1n\right)^n-e\right];\]\n2. \[\lim_{n\to\infty}\left(\frac{a^{1/n}+b^{1/n}+c^{1/n}}3\right)^n,\]\n   其中 \(a>0,b>0,c>0\)。', '1. \(-\frac e2\)。\n2. \(\sqrt[3]{abc}\)。', '1. 由\n   \[\left(1+\frac1n\right)^n=e^{1-\frac1{2n}+o(1/n)}\]\n   得\n   \[n\left[\left(1+\frac1n\right)^n-e\right]\to-\frac e2.\]\n2. 由 \(a^{1/n}=1+\frac{\ln a}{n}+o(1/n)\) 等展开，\n   \[\frac{a^{1/n}+b^{1/n}+c^{1/n}}3 =1+\frac{\ln\sqrt[3]{abc}}n+o(1/n).\]\n   因此原极限为 \(e^{\ln\sqrt[3]{abc}}=\sqrt[3]{abc}\)。', '2010 年第一届全国大学生数学竞赛决赛（非数学专业） 求下列极限： 1. [ n n [ (1+ 1n ) n-e ]; ] 2. [ n ( a 1/n +b 1/n +c 1/n 3 ) n, ] 其中 (a>0,b>0,c>0 )。 1. (- e2 )。 2. ( [3] abc )。 1. 由 [ (1+ 1n ) n=e 1- 1 2n +o(1/n) ] 得 [n [ (1+ 1n ) n-e ] - e2. ] 2. 由 (a 1/n =1+ a n +o(1/n) ) 等展开， [ a 1/n +b 1/n +c 1/n 3 =1+ [3] abc n+o(1/n). ] 因此原极限为 (e [3] abc = [3] abc )。', 1, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
