INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (15, 2, '7', 7, 'proof', 12.00, '是否存在 \(\mathbb R\) 上的可微函数 \(f(x)\)，使得\n\[f(f(x))=1+x^2+x^4-x^3-x^5?\]\n若存在，请给出一个例子；若不存在，请给出证明。', '不存在满足条件的可微函数。', '记 \(g(x)=1+x^2+x^4-x^3-x^5\)。方程 \(g(x)=x\) 等价于\n\[-(x-1)(x^4+x^2+1)=0,\]\n故 \(g\) 只有一个实不动点 \(x=1\)。\n\n设存在所求 \(f\)，令 \(t=f(1)\)。由 \(f(f(1))=g(1)=1\) 得 \(f(t)=1\)，进而 \(g(t)=f(f(t))=f(1)=t\)。由不动点唯一性得 \(t=1\)，即 \(f(1)=1\)。\n\n于是对 \(g=f\circ f\) 在 \(1\) 处求导，\n\[g''(1)=[f''(1)]^2\ge0.\]\n但直接求导得\n\[g''(1)=2+4-3-5=-2,\]\n矛盾。因此不存在。', '2010 年第一届全国大学生数学竞赛决赛（非数学专业） 是否存在 ( R ) 上的可微函数 (f(x) )，使得 [f(f(x))=1+x 2+x 4-x 3-x 5? ] 若存在，请给出一个例子；若不存在，请给出证明。 不存在满足条件的可微函数。 记 (g(x)=1+x 2+x 4-x 3-x 5 )。方程 (g(x)=x ) 等价于 [-(x-1)(x 4+x 2+1)=0, ] 故 (g ) 只有一个实不动点 (x=1 )。 设存在所求 (f )，令 (t=f(1) )。由 (f(f(1))=g(1)=1 ) 得 (f(t)=1 )，进而 (g(t)=f(f(t))=f(1)=t )。由不动点唯一性得 (t=1 )，即 (f(1)=1 )。 于是对 (g=f f ) 在 (1 ) 处求导， [g''(1)=[f''(1)] 2 0. ] 但直接求导得 [g''(1)=2+4-3-5=-2, ] 矛盾。因此不存在。', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
INSERT INTO question_knowledge_points (question_id, knowledge_point_id, is_primary) VALUES (15, 2, TRUE) ON CONFLICT DO NOTHING;
