INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES (16, 2, '8', 8, 'proof', 12.00, '设 \(f(x)\) 在 \([0,\infty)\) 上一致连续，并且对于每个固定的 \(x\in[0,\infty)\)，当自然数 \(n\to\infty\) 时 \(f(x+n)\to0\)。证明函数序列\n\[\{f(x+n):n=1,2,\ldots\}\]\n在 \([0,1]\) 上一致收敛于 \(0\)。', '函数序列在 \([0,1]\) 上一致收敛于 \(0\)。', '任给 \(\varepsilon>0\)。由 \(f\) 在 \([0,\infty)\) 上一致连续，存在 \(\delta>0\)，使 \(|x_1-x_2|<\delta\) 时 \(|f(x_1)-f(x_2)|<\varepsilon/2\)。\n\n在 \([0,1]\) 中取有限个分点 \(0=x_0<x_1<\cdots<x_m=1\)，使相邻距离小于 \(\delta\)。对每个 \(x_j\)，由逐点收敛可取 \(N_j\)，使 \(n>N_j\) 时 \(|f(x_j+n)|<\varepsilon/2\)。令 \(N=\max_jN_j\)。\n\n任取 \(x\in[0,1]\)，选取与它距离小于 \(\delta\) 的分点 \(x_j\)。当 \(n>N\) 时，\n\[|f(x+n)|\le|f(x+n)-f(x_j+n)|+|f(x_j+n)|<\varepsilon.\]\n\(N\) 与 \(x\) 无关，因此在 \([0,1]\) 上一致收敛于 \(0\)。', '2010 年第一届全国大学生数学竞赛决赛（非数学专业） 设 (f(x) ) 在 ([0, ) ) 上一致连续，并且对于每个固定的 (x [0, ) )，当自然数 (n ) 时 (f(x+n) 0 )。证明函数序列 [ f(x+n):n=1,2, ] 在 ([0,1] ) 上一致收敛于 (0 )。 函数序列在 ([0,1] ) 上一致收敛于 (0 )。 任给 ( >0 )。由 (f ) 在 ([0, ) ) 上一致连续，存在 ( >0 )，使 (|x 1-x 2|< ) 时 (|f(x 1)-f(x 2)|< /2 )。 在 ([0,1] ) 中取有限个分点 (0=x 0<x 1< <x m=1 )，使相邻距离小于 ( )。对每个 (x j )，由逐点收敛可取 (N j )，使 (n>N j ) 时 (|f(x j+n)|< /2 )。令 (N= jN j )。 任取 (x [0,1] )，选取与它距离小于 ( ) 的分点 (x j )。当 (n>N ) 时， [|f(x+n)| |f(x+n)-f(x j+n)|+|f(x j+n)|< . ] (N ) 与 (x ) 无关，因此在 ([0,1] ) 上一致收敛于 (0 )。', 2, 'published') ON CONFLICT (id) DO UPDATE SET stem_md = EXCLUDED.stem_md;
